import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const FitProfile: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();

  // Profile State
  const [gender, setGender] = useState<'Male' | 'Female' | 'Other'>('Male');
  const [selectedSize, setSelectedSize] = useState('M');
  const [sliderValue, setSliderValue] = useState(2);
  const [selectedBrand, setSelectedBrand] = useState('');
  const [waistSize, setWaistSize] = useState('');
  const [breastSize, setBreastSize] = useState(''); 
  const [braCup, setBraCup] = useState('');
  const [bodyShape, setBodyShape] = useState('');
  const [showFitInfo, setShowFitInfo] = useState(false);
  const [showBodyShapeModal, setShowBodyShapeModal] = useState(false);

  // Height and Weight
  const [heightUnit, setHeightUnit] = useState<'ft' | 'cm'>('ft');
  const [heightFt, setHeightFt] = useState('');
  const [heightIn, setHeightIn] = useState('');
  const [heightCm, setHeightCm] = useState('');
  const [weight, setWeight] = useState('');

  // Form Validation
  const isHeightValid = heightUnit === 'cm' 
    ? heightCm.trim() !== '' 
    : (heightFt.trim() !== '' && heightIn.trim() !== '');

  const isWeightValid = weight.trim() !== '';
  const isBodyShapeValid = bodyShape !== '';

  // Breast size & Cup is mandatory ONLY if gender is Female
  const isBreastSizeValid = gender === 'Female' ? (breastSize.trim() !== '' && braCup !== '') : true;

  // Brand and measurement fields are mandatory
  const isFormValid = selectedBrand !== '' && isHeightValid && isWeightValid && isBodyShapeValid && isBreastSizeValid;

  // Helper to handle non-negative number inputs
  const handleNumericInput = (setter: (val: string) => void) => (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val === '') {
      setter(val);
      return;
    }
    const num = parseFloat(val);
    if (!isNaN(num) && num >= 0) {
      setter(val);
    }
  };

  const handleBack = () => {
    if (window.history.state && window.history.state.idx > 0) {
      navigate(-1);
    } else {
      navigate('/home');
    }
  };

  const getShirtPath = (val: number) => {
      switch(val) {
          case 1: return "M100,28 L126,34 L138,52 L120,60 L116,132 L84,132 L80,60 L62,52 L74,34 Z"; // Slim
          case 2: return "M100,28 L132,34 L148,54 L128,64 L128,132 L72,132 L72,64 L52,54 L68,34 Z"; // Regular
          case 3: return "M100,28 L140,34 L160,56 L138,68 L142,132 L58,132 L62,68 L40,56 L60,34 Z"; // Relaxed
          default: return "";
      }
  };

  // Enhanced Body Shapes Data with Detailed Descriptions
  const maleShapes = [
    { 
        id: 'average', 
        label: 'Average', 
        desc: 'Balanced proportions',
        features: ['Shoulders and hips are aligned', 'Waist is slightly smaller than chest', 'Common athletic build'],
        styling: 'Most styles fit well. Slim or regular cuts highlight your proportions.',
        svgPath: 'M30,20 L70,20 L75,35 L65,80 L35,80 L25,35 Z' 
    },
    { 
        id: 'inverted_triangle', 
        label: 'Inverted Triangle', 
        desc: 'Broad shoulders, narrow waist',
        features: ['Shoulders significantly wider than hips', 'Developed chest and shoulders', 'Narrow waist and hips'],
        styling: 'Regular fit shirts and straight leg trousers balance the silhouette.',
        svgPath: 'M20,20 L80,20 L65,80 L35,80 Z'
    },
    { 
        id: 'rectangle', 
        label: 'Rectangle', 
        desc: 'Uniform width',
        features: ['Shoulders, chest, and waist are similar width', 'Straight torso line', 'Few curves'],
        styling: 'Structured jackets and layered tops add dimension.',
        svgPath: 'M30,20 L70,20 L70,80 L30,80 Z'
    },
    { 
        id: 'oval', 
        label: 'Oval', 
        desc: 'Midsection prominence',
        features: ['Torso is wider than shoulders and hips', 'Softer, rounder appearance', 'Short neck appearance sometimes'],
        styling: 'Vertical stripes and dark colors have a slimming effect. Relaxed fits offer comfort.',
        svgPath: 'M40,20 L60,20 C85,35 85,65 60,80 L40,80 C15,65 15,35 40,20 Z'
    }
  ];

  const femaleShapes = [
    { 
        id: 'hourglass', 
        label: 'Hourglass', 
        desc: 'Curvy and balanced',
        features: ['Bust and hips are roughly same width', 'Well-defined, narrow waist', 'Curvy silhouette'],
        styling: 'Fitted tops and high-waisted bottoms accentuate curves.',
        svgPath: 'M30,20 L70,20 C60,40 60,40 70,60 L75,80 L25,80 L30,60 C40,40 40,40 30,20 Z'
    },
    { 
        id: 'pear', 
        label: 'Pear (Triangle)', 
        desc: 'Hips wider than bust',
        features: ['Hips are wider than shoulders/bust', 'Defined waist', 'Fuller hips and thighs'],
        styling: 'A-line skirts and boat-neck tops balance proportions.',
        svgPath: 'M40,20 L60,20 L75,80 L25,80 Z'
    },
    { 
        id: 'apple', 
        label: 'Apple (Round)', 
        desc: 'Fuller midsection',
        features: ['Shoulders and bust are broader', 'Undefined waist', 'Fuller midsection'],
        styling: 'Empire waistlines and V-necks elongate the torso.',
        svgPath: 'M30,20 L70,20 C80,40 80,50 65,80 L35,80 C20,50 20,40 30,20 Z'
    },
    { 
        id: 'rectangle', 
        label: 'Rectangle (Straight)', 
        desc: 'Straight silhouette',
        features: ['Shoulders, waist and hips align', 'Athletic look', 'Little to no waist definition'],
        styling: 'Belts and ruffled tops create the illusion of curves.',
        svgPath: 'M35,20 L65,20 L65,80 L35,80 Z'
    }
  ];

  const currentShapes = gender === 'Female' ? femaleShapes : maleShapes;

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col bg-[#f7f7f7] dark:bg-[#191919] overflow-x-hidden font-display">
      <div className="sticky top-0 z-10 flex items-center bg-[#f7f7f7]/95 backdrop-blur-sm dark:bg-[#191919]/95 p-6 pb-4 justify-between border-b border-gray-100 dark:border-gray-800">
        <button onClick={handleBack} className="text-black dark:text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors">
          <span className="material-symbols-outlined text-2xl">arrow_back</span>
        </button>
        <h2 className="text-black dark:text-white text-xl font-bold leading-tight tracking-[-0.015em] flex-1 text-center pr-12">Fit Profile</h2>
      </div>

      <div className="flex-1 flex flex-col px-6 pt-6 pb-40 gap-8">

        {/* Gender Selection */}
        <div className="flex flex-col gap-3">
            <p className="text-black dark:text-white text-lg font-bold leading-normal">Gender</p>
            <div className="flex p-1 bg-white dark:bg-[#212121] rounded-2xl border border-[#e5e5e5] dark:border-[#474747]">
                {['Male', 'Female', 'Other'].map((g) => (
                    <button 
                        key={g}
                        onClick={() => {
                            setGender(g as any);
                            setBodyShape(''); // Reset shape on gender change
                            if (g !== 'Female') {
                                setBreastSize('');
                                setBraCup('');
                            }
                        }}
                        className={`flex-1 py-3 rounded-xl text-sm font-bold transition-all ${
                            gender === g 
                            ? 'bg-black dark:bg-white text-white dark:text-black shadow-md' 
                            : 'text-gray-500 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-[#303030]'
                        }`}
                    >
                        {g}
                    </button>
                ))}
            </div>
        </div>

        {/* Brand */}
        <div className="flex flex-col gap-3">
          <label className="flex flex-col w-full">
            <p className="text-black dark:text-white text-lg font-bold leading-normal pb-3">Preferred Brand <span className="text-red-500">*</span></p>
            <div className="relative">
              <select 
                value={selectedBrand}
                onChange={(e) => setSelectedBrand(e.target.value)}
                className="flex w-full min-w-0 flex-1 resize-none overflow-hidden rounded-2xl text-black dark:text-white focus:outline-0 focus:ring-2 focus:ring-black/20 dark:focus:ring-white/20 border border-[#e5e5e5] dark:border-[#474747] bg-white dark:bg-[#212121] h-16 placeholder:text-[#ababab] p-[18px] text-lg font-medium leading-normal appearance-none transition-all hover:border-gray-400 dark:hover:border-gray-500"
              >
                <option disabled value="">Select a brand</option>
                <option value="hm">H&M</option>
                <option value="zara">Zara</option>
                <option value="uniqlo">Uniqlo</option>
                <option value="nike">Nike</option>
                <option value="adidas">Adidas</option>
              </select>
            </div>
          </label>
          <p className="text-sm text-gray-500 dark:text-gray-400 pl-1 font-medium">We'll use this brand as a reference for sizing.</p>
        </div>

        {/* Height Section */}
        <div className="flex flex-col gap-3">
          <div className="flex justify-between items-center pb-2">
            <p className="text-black dark:text-white text-lg font-bold leading-normal">Height <span className="text-red-500">*</span></p>
            <div className="flex bg-gray-200 dark:bg-[#303030] rounded-lg p-1">
              <button 
                onClick={() => setHeightUnit('ft')}
                className={`px-3 py-1 rounded-md text-sm font-bold transition-all ${heightUnit === 'ft' ? 'bg-white dark:bg-[#474747] text-black dark:text-white shadow-sm' : 'text-gray-500 dark:text-gray-400'}`}
              >
                FT
              </button>
              <button 
                onClick={() => setHeightUnit('cm')}
                className={`px-3 py-1 rounded-md text-sm font-bold transition-all ${heightUnit === 'cm' ? 'bg-white dark:bg-[#474747] text-black dark:text-white shadow-sm' : 'text-gray-500 dark:text-gray-400'}`}
              >
                CM
              </button>
            </div>
          </div>

          {heightUnit === 'ft' ? (
            <div className="flex gap-4">
              <div className="relative flex-1">
                <input 
                  value={heightFt}
                  onChange={handleNumericInput(setHeightFt)}
                  className="form-input w-full rounded-2xl text-black dark:text-white focus:outline-0 focus:ring-2 focus:ring-black/20 dark:focus:ring-white/20 border border-[#e5e5e5] dark:border-[#474747] bg-white dark:bg-[#212121] h-16 p-[18px] pr-20 text-lg font-medium" 
                  placeholder="5" 
                  type="number"
                  min="0"
                />
                <span className="absolute right-14 top-1/2 -translate-y-1/2 text-[#ababab] font-bold pointer-events-none">ft</span>
              </div>
              <div className="relative flex-1">
                <input 
                  value={heightIn}
                  onChange={handleNumericInput(setHeightIn)}
                  className="form-input w-full rounded-2xl text-black dark:text-white focus:outline-0 focus:ring-2 focus:ring-black/20 dark:focus:ring-white/20 border border-[#e5e5e5] dark:border-[#474747] bg-white dark:bg-[#212121] h-16 p-[18px] pr-20 text-lg font-medium" 
                  placeholder="10" 
                  type="number"
                  min="0"
                />
                <span className="absolute right-14 top-1/2 -translate-y-1/2 text-[#ababab] font-bold pointer-events-none">in</span>
              </div>
            </div>
          ) : (
            <div className="relative">
              <input 
                value={heightCm}
                onChange={handleNumericInput(setHeightCm)}
                className="form-input w-full rounded-2xl text-black dark:text-white focus:outline-0 focus:ring-2 focus:ring-black/20 dark:focus:ring-white/20 border border-[#e5e5e5] dark:border-[#474747] bg-white dark:bg-[#212121] h-16 p-[18px] pr-20 text-lg font-medium" 
                placeholder="178" 
                type="number"
                min="0"
              />
              <span className="absolute right-14 top-1/2 -translate-y-1/2 text-[#ababab] font-bold pointer-events-none">cm</span>
            </div>
          )}
        </div>

        {/* Weight & Waist Section */}
        <div className="flex gap-4">
            <div className="flex-1 flex flex-col gap-3">
               <p className="text-black dark:text-white text-lg font-bold leading-normal pb-0">Weight <span className="text-red-500">*</span></p>
               <div className="relative">
                  <input 
                    value={weight}
                    onChange={handleNumericInput(setWeight)}
                    className="form-input w-full rounded-2xl text-black dark:text-white focus:outline-0 focus:ring-2 focus:ring-black/20 dark:focus:ring-white/20 border border-[#e5e5e5] dark:border-[#474747] bg-white dark:bg-[#212121] h-16 p-[18px] pr-14 text-lg font-medium" 
                    placeholder="70" 
                    type="number"
                    min="0"
                  />
                  <span className="absolute right-6 top-1/2 -translate-y-1/2 text-[#ababab] font-bold pointer-events-none">kg</span>
               </div>
            </div>

            <div className="flex-1 flex flex-col gap-3">
               <p className="text-black dark:text-white text-lg font-bold leading-normal pb-0">Waist <span className="text-gray-400 text-xs font-normal ml-1">(Optional)</span></p>
               <div className="relative">
                  <input 
                    value={waistSize}
                    onChange={handleNumericInput(setWaistSize)}
                    className="form-input w-full rounded-2xl text-black dark:text-white focus:outline-0 focus:ring-2 focus:ring-black/20 dark:focus:ring-white/20 border border-[#e5e5e5] dark:border-[#474747] bg-white dark:bg-[#212121] h-16 p-[18px] pr-14 text-lg font-medium" 
                    placeholder="32" 
                    type="number"
                    min="0"
                  />
                  <span className="absolute right-6 top-1/2 -translate-y-1/2 text-[#ababab] font-bold pointer-events-none">in</span>
               </div>
            </div>
        </div>

        {/* Body Shape Selector */}
        <div className="flex flex-col gap-4">
            <div className="flex justify-between items-center">
                <p className="text-black dark:text-white text-lg font-bold leading-normal">Body Shape <span className="text-red-500">*</span></p>
                <button 
                  onClick={() => setShowBodyShapeModal(true)}
                  className="text-xs font-bold text-blue-500 dark:text-blue-400 cursor-pointer hover:underline"
                >
                  What's this?
                </button>
            </div>
            <div className="grid grid-cols-2 gap-3">
                {currentShapes.map((shape) => (
                    <button
                        key={shape.id}
                        onClick={() => setBodyShape(shape.id)}
                        className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all duration-200 gap-1 ${
                            bodyShape === shape.id 
                            ? 'bg-black dark:bg-white text-white dark:text-black border-black dark:border-white shadow-lg' 
                            : 'bg-white dark:bg-[#212121] text-black dark:text-white border-[#e5e5e5] dark:border-[#474747] hover:bg-gray-50 dark:hover:bg-[#303030]'
                        }`}
                    >
                        <span className="text-sm font-bold">{shape.label}</span>
                        <span className={`text-[10px] text-center ${bodyShape === shape.id ? 'opacity-80' : 'text-gray-400'}`}>{shape.desc}</span>
                    </button>
                ))}
            </div>
        </div>

        {/* T-Shirt Size */}
        <div className="flex flex-col gap-4">
          <h3 className="text-black dark:text-white tracking-tight text-lg font-bold leading-tight text-left">Usual T-Shirt Size</h3>
          <div className="flex gap-2 flex-wrap">
            {['XS', 'S', 'M', 'L', 'XL', 'XXL'].map((size) => (
              <button 
                key={size}
                onClick={() => setSelectedSize(size)}
                className={`flex h-14 min-w-[3.5rem] flex-1 shrink-0 items-center justify-center rounded-2xl transition-all duration-200 ${
                  selectedSize === size 
                    ? 'bg-[#1C1C1E] dark:bg-white text-white dark:text-black font-black border border-transparent' 
                    : 'border border-[#e5e5e5] dark:border-[#474747] bg-white dark:bg-[#212121] text-black dark:text-white font-bold hover:bg-gray-50 dark:hover:bg-[#303030]'
                }`}
              >
                <p className="text-lg leading-normal">{size}</p>
              </button>
            ))}
          </div>
        </div>

        {/* Breast Size & Cup - Conditionally Rendered for Females */}
        {gender === 'Female' && (
             <div className="flex flex-col gap-5 animate-in fade-in slide-in-from-top-2 duration-500">
                <div className="flex flex-col gap-3">
                    <p className="text-black dark:text-white text-lg font-bold leading-normal">Breast Size <span className="text-red-500">*</span></p>
                    <div className="relative flex items-center">
                        <input 
                            value={breastSize}
                            onChange={handleNumericInput(setBreastSize)}
                            className="form-input flex w-full min-w-0 flex-1 resize-none overflow-hidden rounded-2xl text-black dark:text-white focus:outline-0 focus:ring-2 focus:ring-black/20 dark:focus:ring-white/20 border border-[#e5e5e5] dark:border-[#474747] bg-white dark:bg-[#212121] h-16 placeholder:text-[#ababab] p-[18px] pr-20 text-lg font-medium leading-normal transition-all hover:border-gray-400 dark:hover:border-gray-500" 
                            placeholder="e.g., 34" 
                            type="number"
                            min="0"
                        />
                        <span className="absolute right-6 text-[#ababab] text-base font-bold pointer-events-none">inches</span>
                    </div>
                </div>

                <div className="flex flex-col gap-3">
                    <p className="text-black dark:text-white text-lg font-bold leading-normal">Bra Cup <span className="text-red-500">*</span></p>
                    <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
                        {['A', 'B', 'C', 'D', 'DD', 'E', 'F', 'G+'].map((cup) => (
                            <button 
                                key={cup}
                                onClick={() => setBraCup(cup)}
                                className={`h-14 min-w-[4rem] rounded-2xl flex items-center justify-center border transition-all ${
                                    braCup === cup
                                    ? 'bg-black dark:bg-white text-white dark:text-black border-transparent font-black shadow-lg'
                                    : 'bg-white dark:bg-[#212121] text-black dark:text-white border-[#e5e5e5] dark:border-[#474747] font-bold hover:bg-gray-50 dark:hover:bg-[#303030]'
                                }`}
                            >
                                {cup}
                            </button>
                        ))}
                    </div>
                </div>

                <p className="text-sm text-gray-500 dark:text-gray-400 pl-1 font-medium -mt-2">Used to recommend better fitting tops and dresses.</p>
            </div>
        )}

        {/* Fit Preference - Improved Design */}
        <div className="flex flex-col gap-6 pt-4 relative">
          <div className="flex justify-between items-center relative z-30">
            <h3 className="text-black dark:text-white text-lg font-bold leading-tight">Fit Preference</h3>
            <button 
                onClick={() => setShowFitInfo(!showFitInfo)}
                className="h-8 w-8 flex items-center justify-center rounded-full bg-gray-100 dark:bg-white/10 text-gray-500 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-white/20 transition-colors"
            >
                <span className="material-symbols-outlined text-[18px]">info</span>
            </button>
          </div>

          {/* Info Tooltip */}
          {showFitInfo && (
              <>
                <div className="fixed inset-0 z-20 bg-black/5 backdrop-blur-[1px] cursor-default transition-opacity" onClick={() => setShowFitInfo(false)}></div>
                <div className="absolute top-12 right-0 z-30 w-[85vw] max-w-[320px] bg-white dark:bg-[#1E1E1E] rounded-3xl shadow-2xl border border-gray-100 dark:border-white/10 p-6 animate-in fade-in zoom-in-95 slide-in-from-top-2 duration-300 origin-top-right ring-1 ring-black/5">
                    <div className="flex justify-between items-center mb-4 border-b border-gray-100 dark:border-white/5 pb-2">
                        <h4 className="text-xs font-black uppercase tracking-widest text-gray-900 dark:text-white">Fit Guide</h4>
                        <button onClick={() => setShowFitInfo(false)} className="text-gray-400 hover:text-black dark:hover:text-white transition-colors">
                            <span className="material-symbols-outlined text-sm">close</span>
                        </button>
                    </div>
                    <div className="flex flex-col gap-4">
                        <div className="flex gap-3 items-start">
                            <div className="mt-1.5 h-2 w-2 rounded-full bg-blue-500 shrink-0 shadow-[0_0_8px_rgba(59,130,246,0.5)]"></div>
                            <div>
                                <p className="text-sm font-bold text-black dark:text-white">Slim Fit</p>
                                <p className="text-xs text-gray-500 dark:text-gray-400 leading-relaxed mt-0.5">Cut closer to the body. Higher armholes and tapered sleeves for a sharp, tailored look.</p>
                            </div>
                        </div>
                        <div className="flex gap-3 items-start">
                            <div className="mt-1.5 h-2 w-2 rounded-full bg-green-500 shrink-0 shadow-[0_0_8px_rgba(34,197,94,0.5)]"></div>
                            <div>
                                <p className="text-sm font-bold text-black dark:text-white">Standard Fit</p>
                                <p className="text-xs text-gray-500 dark:text-gray-400 leading-relaxed mt-0.5">Classic cut with comfortable room in the chest and waist. The most versatile fit.</p>
                            </div>
                        </div>
                        <div className="flex gap-3 items-start">
                            <div className="mt-1.5 h-2 w-2 rounded-full bg-purple-500 shrink-0 shadow-[0_0_8px_rgba(168,85,247,0.5)]"></div>
                            <div>
                                <p className="text-sm font-bold text-black dark:text-white">Relaxed Fit</p>
                                <p className="text-xs text-gray-500 dark:text-gray-400 leading-relaxed mt-0.5">Generous cut with draped shoulders and a wider body. Maximum comfort and casual style.</p>
                            </div>
                        </div>
                    </div>
                </div>
              </>
          )}

          {/* Visualizer */}
          <div className="w-full h-48 bg-gray-100 dark:bg-[#1C1C1E] rounded-[2rem] flex flex-col items-center justify-center relative overflow-hidden border border-gray-200 dark:border-[#333]">
              {/* Background grid */}
              <div className="absolute inset-0 opacity-[0.03] dark:opacity-[0.1]" style={{ backgroundImage: 'radial-gradient(circle, currentColor 1px, transparent 1px)', backgroundSize: '16px 16px' }}></div>

              <div className="relative h-full w-full flex items-center justify-center top-2">
                 {/* Body Silhouette */}
                  <svg width="140" height="150" viewBox="0 0 200 160" className="absolute text-gray-300 dark:text-[#333] transition-all duration-300">
                     <path d="M100,28 L122,34 L122,50 L115,132 L85,132 L78,50 L78,34 L100,28 Z" fill="currentColor" />
                  </svg>

                  {/* Dynamic Shirt */}
                  <svg width="200" height="160" viewBox="0 0 200 160" className="absolute transition-all duration-500 ease-out text-blue-600 dark:text-blue-400 z-10">
                      <path 
                        d={getShirtPath(sliderValue)} 
                        fill="none" 
                        stroke="currentColor" 
                        strokeWidth="3" 
                        strokeLinecap="round" 
                        strokeLinejoin="round"
                        className="drop-shadow-lg transition-all duration-500"
                      />
                      {/* Fill with low opacity */}
                      <path 
                        d={getShirtPath(sliderValue)} 
                        fill="currentColor" 
                        fillOpacity="0.1"
                        className="transition-all duration-500"
                      />
                  </svg>
              </div>

              {/* Tag */}
              <div className="absolute top-4 right-4">
                  <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1.5 rounded-full border shadow-sm transition-colors duration-300 ${
                      sliderValue === 1 ? 'bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-900/30' :
                      sliderValue === 2 ? 'bg-green-50 text-green-600 border-green-100 dark:bg-green-900/20 dark:text-green-400 dark:border-green-900/30' :
                      'bg-purple-50 text-purple-600 border-purple-100 dark:bg-purple-900/20 dark:text-purple-400 dark:border-purple-900/30'
                  }`}>
                      {sliderValue === 1 ? 'Tight' : sliderValue === 2 ? 'Standard' : 'Loose'}
                  </span>
              </div>
          </div>

          <div className="w-full bg-[#efefef] dark:bg-[#252525] rounded-[24px] p-1.5 h-[72px] relative flex items-center shadow-inner">
               {/* Sliding Active Indicator */}
               <div 
