                                <div className="absolute inset-0 flex items-center justify-center">
                                    <span className="material-symbols-outlined text-pink-500 text-2xl animate-pulse">brush</span>
                                </div>
                            </div>
                            <p className="text-sm font-bold text-gray-500 animate-pulse">Designing your look...</p>
                        </div>
                    ) : (
                        <>
                            <img src={generatedImage!} alt="Generated Fashion" className="w-full h-full object-cover" />
                            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-end p-6">
