        console.error("Camera access denied:", err);
        setError("Please enable camera access to use Virtual Try-On.");
      }
    };

    startCamera();

    return () => {
      if (localStream) {
        localStream.getTracks().forEach(track => track.stop());
      }
    };
  }, [facingMode]);

  const handleBack = () => {
    if (stream) {
        stream.getTracks().forEach(track => track.stop());
    }
    navigate(-1);
  };

  const toggleCamera = () => {
    // Stop current stream to ensure clean switch
    if (stream) {
        stream.getTracks().forEach(track => track.stop());
        setStream(null); 
    }
    setFacingMode(prev => prev === 'user' ? 'environment' : 'user');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const imageUrl = URL.createObjectURL(file);

      const newItem = {
        id: wardrobe.length > 0 ? Math.max(...wardrobe.map(i => i.id)) + 1 : 0,
        name: 'Custom Upload',
        brand: 'My Closet',
        price: '',
        image: imageUrl,
        category: 'Custom'
      };

      setWardrobe(prev => [...prev, newItem]);
      setSelectedItem(newItem.id);
    }
  };

  const handleAddToCart = () => {
      const cart = JSON.parse(localStorage.getItem('zipright_cart') || '[]');

      // Parse price safely (remove currency symbols and commas)
      const priceString = currentItem.price || '0';
      const priceNum = parseFloat(priceString.replace(/[^0-9.]/g, '')) || 0;

      // Check if item exists to update quantity, else add new
      const existingItemIndex = cart.findIndex((item: any) => 
        item.title === currentItem.name && item.brand === currentItem.brand
      );

      let newCart;
      if (existingItemIndex > -1) {
          newCart = [...cart];
          newCart[existingItemIndex].quantity = (newCart[existingItemIndex].quantity || 1) + 1;
      } else {
          const newItem = {
              id: Date.now(),
              title: currentItem.name,
              brand: currentItem.brand,
              price: priceNum,
              size: 'M', // Default size for AR items
              image: currentItem.image,
              quantity: 1
          };
          newCart = [...cart, newItem];
      }

      localStorage.setItem('zipright_cart', JSON.stringify(newCart));

      // Show Toast
      setShowToast(true);
      setTimeout(() => setShowToast(false), 2500);
  };

  const toggleWishlist = () => {
      const wishlist = JSON.parse(localStorage.getItem('zipright_wishlist') || '[]');
      let newWishlist;

      if (isLiked) {
          // Remove
          newWishlist = wishlist.filter((item: any) => item.title !== currentItem.name);
      } else {
          // Add
          const newItem = {
              id: Date.now(),
              title: currentItem.name,
              brand: currentItem.brand,
              price: currentItem.price,
              image: currentItem.image,
              verified: true
          };
          newWishlist = [...wishlist, newItem];
      }

      localStorage.setItem('zipright_wishlist', JSON.stringify(newWishlist));
      setIsLiked(!isLiked);
      if (navigator.vibrate) navigator.vibrate(10);
  };

  return (
    <div className="relative h-screen w-full bg-black text-white overflow-hidden font-display select-none">

      {/* Toast Notification */}
      <div className={`fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-white text-black px-6 py-3 rounded-full shadow-xl flex items-center gap-2 transition-all duration-300 pointer-events-none ${showToast ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4'}`}>
         <span className="material-symbols-outlined text-green-600">check_circle</span>
         <span className="font-bold text-sm">Added to Cart</span>
      </div>

      {/* Hidden File Input for Sidebar + Button */}
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleImageUpload} 
      />

      {/* 1. Live Camera Background */}
      <div className="absolute inset-0 z-0 bg-[#101010]">
        {error ? (
            <div className="flex flex-col items-center justify-center h-full p-6 text-center">
                <span className="material-symbols-outlined text-gray-500 text-5xl mb-4">no_photography</span>
                <p className="text-gray-400 font-bold">{error}</p>
            </div>
        ) : (
            <video 
                ref={videoRef}
                autoPlay 
                playsInline 
                muted 
                // Mirror the video only when using the front (user) camera
                className={`w-full h-full object-cover transition-transform duration-500 ${facingMode === 'user' ? 'scale-x-[-1]' : 'scale-x-1'}`} 
            />
        )}

        {/* Dark overlay for UI visibility */}
        <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-transparent to-black/80 pointer-events-none"></div>
      </div>

      {/* 2. Top Minimal Navbar */}
      <div className="absolute top-0 left-0 right-0 z-50 flex items-center justify-between px-6 py-6">
        <button 
          onClick={handleBack} 
          className="h-10 w-10 flex items-center justify-center rounded-full bg-black/20 backdrop-blur-md border border-white/10 active:scale-95 transition-all"
        >
          <span className="material-symbols-outlined text-white text-[20px]">arrow_back</span>
        </button>

        <div className="flex flex-col items-center opacity-90 drop-shadow-md">
          <span className="text-[10px] font-black uppercase tracking-[0.2em] text-white/80">AR Live Mode</span>
        </div>

        <div className="flex items-center gap-3">
           {/* Camera Toggle Button */}
           <button 
             onClick={toggleCamera}
             className="h-10 w-10 flex items-center justify-center rounded-full bg-black/20 backdrop-blur-md border border-white/10 active:scale-95 transition-all hover:bg-white/10"
           >
              <span className="material-symbols-outlined text-white text-[18px]">cameraswitch</span>
           </button>
        </div>
      </div>

      {/* 3. AR Cloth Overlay (Smart Mirror Effect) */}
      <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
          <div className="relative w-full max-w-sm h-[70vh] flex items-center justify-center opacity-85 mix-blend-normal">
              <img 
                src={currentItem.image} 
                alt="AR Cloth"
                className="w-full h-full object-contain drop-shadow-2xl transition-all duration-500 ease-out animate-in fade-in zoom-in-95"
                key={currentItem.id}
              />

              {/* Optional: Guide Silhouette for positioning */}
              <div className="absolute inset-0 border-2 border-white/10 rounded-[4rem] pointer-events-none"></div>
          </div>
      </div>

      {/* 4. Left Sidebar - Clothing Selector */}
      <div className="absolute left-4 top-1/2 -translate-y-1/2 z-40 w-16 max-h-[60vh] flex flex-col items-center gap-4 py-4 rounded-[2rem] bg-black/30 backdrop-blur-xl border border-white/10 overflow-y-auto no-scrollbar">
          {wardrobe.map((item) => (
              <button
                key={item.id}
                onClick={() => setSelectedItem(item.id)}
                className={`relative h-12 w-12 rounded-2xl flex-shrink-0 overflow-hidden border-2 transition-all duration-300 ${selectedItem === item.id ? 'border-white scale-110 shadow-[0_0_15px_rgba(255,255,255,0.5)]' : 'border-transparent opacity-60 hover:opacity-100'}`}
              >
                  <img src={item.image} className="w-full h-full object-cover" alt={item.name} />
              </button>
          ))}
          {/* Functional Upload Button */}
          <button 
             onClick={() => fileInputRef.current?.click()}
             className="h-10 w-10 mt-2 rounded-full border border-white/30 flex items-center justify-center text-white hover:bg-white hover:text-black transition-colors"
          >
              <span className="material-symbols-outlined text-[20px]">add</span>
          </button>
      </div>

      {/* 5. Bottom Info */}
      <div className="absolute bottom-0 left-0 right-0 p-6 pb-8 z-50 bg-gradient-to-t from-black via-black/80 to-transparent">
          <div className="flex flex-col items-center">

              {/* Item Info - Price Removed */}
              <div className="mb-6 text-center">
                  <h2 className="text-xl font-black text-white leading-tight shadow-black drop-shadow-md">{currentItem.name}</h2>
                  <p className="text-xs font-bold text-gray-300 uppercase tracking-wide mt-1">{currentItem.brand}</p>
              </div>

              {/* Action Buttons */}
              <div className="flex gap-3 w-full max-w-sm">
                  <button 
                    onClick={handleAddToCart}
                    className="flex-1 h-12 rounded-xl bg-white text-black font-black uppercase tracking-wider flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(255,255,255,0.2)] active:scale-[0.98] transition-transform hover:bg-gray-100"
