import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const PermissionsOnboarding: React.FC = () => {
  const navigate = useNavigate();

  // Core permissions state synced with global storage
  const [permissions, setPermissions] = useState(() => {
    const stored = localStorage.getItem('zipright_permissions');
    return stored ? JSON.parse(stored) : {
      camera: false,
      location: false,
      contacts: false,
      notifications: true,
      microphone: false,
      photos: true,
      nearby: false
    };
  });

  // Track interactions to enable the continue button
  const [interacted, setInteracted] = useState({
    camera: false,
    location: false,
    contacts: false
  });

  // Persist permissions state
  useEffect(() => {
    localStorage.setItem('zipright_permissions', JSON.stringify(permissions));
  }, [permissions]);

  const requestCamera = async () => {
    try {
      // Native browser trigger
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      // Stop the stream immediately, we only wanted the permission
      stream.getTracks().forEach(track => track.stop());

      const nextPermissions = { ...permissions, camera: true };
      setPermissions(nextPermissions);
      localStorage.setItem('permission_granted', 'true');
      setInteracted(prev => ({ ...prev, camera: true }));
    } catch (err) {
      console.warn("Camera access denied or failed", err);
      setInteracted(prev => ({ ...prev, camera: true }));
    }
    if (navigator.vibrate) navigator.vibrate(10);
  };

  const requestLocation = () => {
    if ("geolocation" in navigator) {
      // Native browser trigger
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const nextPermissions = { ...permissions, location: true };
          setPermissions(nextPermissions);
          localStorage.setItem('permission_granted', 'true');
          setInteracted(prev => ({ ...prev, location: true }));
        },
        (err) => {
          console.warn("Location access denied", err);
          setInteracted(prev => ({ ...prev, location: true }));
        },
        { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
      );
    } else {
      setInteracted(prev => ({ ...prev, location: true }));
    }
    if (navigator.vibrate) navigator.vibrate(10);
  };

  const requestContacts = () => {
    // Simulated system-level prompt as Browsers don't have a standard 'Contacts' API like mobile
    const confirmed = window.confirm("ZipRIGHT would like to access your contacts to help you find friends and share style tips.");
    if (confirmed) {
      const nextPermissions = { ...permissions, contacts: true };
      setPermissions(nextPermissions);
      localStorage.setItem('permission_granted', 'true');
    }
    setInteracted(prev => ({ ...prev, contacts: true }));
    if (navigator.vibrate) navigator.vibrate(10);
  };

  // Button is clickable if the user has interacted with all 3 core prompts
  const isReady = interacted.camera && interacted.location && interacted.contacts;

  const handleContinue = () => {
    if (isReady) {
      navigate('/home');
    }
  };

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col bg-black text-white font-display overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-0 left-0 w-full h-1/2 bg-gradient-to-b from-blue-900/10 to-transparent pointer-events-none"></div>

      <div className="flex-1 flex flex-col px-8 pt-20 pb-12 z-10">
        <div className="flex flex-col gap-4 mb-12">
            <div className="h-14 w-14 rounded-2xl bg-blue-600 flex items-center justify-center shadow-2xl shadow-blue-600/40">
                <span className="material-symbols-outlined text-3xl">verified_user</span>
            </div>
            <h1 className="text-4xl font-black tracking-tight leading-tight">Access Control</h1>
            <p className="text-gray-400 text-base font-medium leading-relaxed">
                ZipRIGHT requires the following permissions to unlock high-precision AI body scanning.
            </p>
        </div>

        <div className="flex flex-col gap-4">
            {/* Camera Permission Card */}
            <div className="p-5 rounded-[2rem] bg-white/5 border border-white/10 flex items-center justify-between group transition-all">
                <div className="flex items-center gap-4">
                    <div className="h-12 w-12 rounded-full bg-blue-500/10 flex items-center justify-center">
                        <span className="material-symbols-outlined text-blue-500">camera</span>
                    </div>
                    <div>
                        <p className="font-bold text-sm">Camera</p>
                        <p className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">Body Scan & Try-on</p>
                    </div>
                </div>
                <button 
                    onClick={requestCamera}
                    disabled={permissions.camera}
                    className={`px-5 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest transition-all ${
                        permissions.camera 
                        ? 'bg-green-500/20 text-green-500 border border-green-500/30' 
                        : 'bg-white text-black hover:bg-gray-200 active:scale-95'
                    }`}
                >
                    {permissions.camera ? '✓ ALLOWED' : 'ALLOW'}
                </button>
            </div>

            {/* Location Permission Card */}
            <div className="p-5 rounded-[2rem] bg-white/5 border border-white/10 flex items-center justify-between group transition-all">
                <div className="flex items-center gap-4">
                    <div className="h-12 w-12 rounded-full bg-purple-500/10 flex items-center justify-center">
                        <span className="material-symbols-outlined text-purple-500">location_on</span>
                    </div>
                    <div>
                        <p className="font-bold text-sm">Location</p>
                        <p className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">Local Style Hubs</p>
                    </div>
                </div>
                <button 
                    onClick={requestLocation}
                    disabled={permissions.location}
                    className={`px-5 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest transition-all ${
                        permissions.location 
                        ? 'bg-green-500/20 text-green-500 border border-green-500/30' 
                        : 'bg-white text-black hover:bg-gray-200 active:scale-95'
                    }`}
                >
                    {permissions.location ? '✓ ALLOWED' : 'ALLOW'}
                </button>
            </div>

            {/* Contacts Permission Card */}
            <div className="p-5 rounded-[2rem] bg-white/5 border border-white/10 flex items-center justify-between group transition-all">
                <div className="flex items-center gap-4">
                    <div className="h-12 w-12 rounded-full bg-orange-500/10 flex items-center justify-center">
                        <span className="material-symbols-outlined text-orange-500">group</span>
                    </div>
                    <div>
                        <p className="font-bold text-sm">Contacts</p>
                        <p className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">Connect Friends</p>
                    </div>
                </div>
                <button 
                    onClick={requestContacts}
                    disabled={permissions.contacts}
                    className={`px-5 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest transition-all ${
                        permissions.contacts 
                        ? 'bg-green-500/20 text-green-500 border border-green-500/30' 
                        : 'bg-white text-black hover:bg-gray-200 active:scale-95'
                    }`}
                >
                    {permissions.contacts ? '✓ ALLOWED' : 'ALLOW'}
                </button>
            </div>
        </div>

        <div className="mt-auto">
            <button 
                onClick={handleContinue}
                className={`w-full h-16 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all duration-300 shadow-xl ${
                    isReady 
                    ? 'bg-white text-black shadow-white/5 opacity-100 cursor-pointer active:scale-[0.98]' 
                    : 'bg-white/10 text-gray-600 cursor-not-allowed border border-white/5 opacity-50'
                }`}
            >
                Continue to App
            </button>
            <p className="text-center text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-6">
                You can change choices in Settings > Permissions
            </p>
        </div>
      </div>
    </div>
  );
};

