import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';

// Fix: Declare google as any to resolve "Cannot find name 'google'" and "Cannot find namespace 'google'" errors
declare const google: any;

const PermissionsOnboarding: React.FC = () => {
  const navigate = useNavigate();

  // Workflow steps: 'permissions' -> 'map' -> 'contacts'
  const [step, setStep] = useState<'permissions' | 'map' | 'contacts'>('permissions');

  // Permissions status
  const [granted, setGranted] = useState({
    camera: localStorage.getItem('zipright_camera') === 'granted',
    location: localStorage.getItem('zipright_location') === 'granted',
    contacts: localStorage.getItem('zipright_contacts') === 'granted'
  });

  // Map state
  const mapRef = useRef<HTMLDivElement>(null);
  const [address, setAddress] = useState('Fetching location...');
  const [isLocating, setIsLocating] = useState(false);
  const [showRetry, setShowRetry] = useState(false);

  // 1. Camera Trigger
  const handleCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      stream.getTracks().forEach(t => t.stop());
      localStorage.setItem('zipright_camera', 'granted');
      setGranted(prev => ({ ...prev, camera: true }));
    } catch (e) {
      console.warn("Camera denied", e);
    }
    if (navigator.vibrate) navigator.vibrate(10);
  };

  // 2. Location Trigger -> Moves to Map
  const handleLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          localStorage.setItem('zipright_location', 'granted');
          setGranted(prev => ({ ...prev, location: true }));
          setStep('map');
          initMap(pos.coords.latitude, pos.coords.longitude);
        },
        (err) => {
          console.warn("Location denied", err);
          alert("Please enable location access to continue.");
        }
      );
    }
    if (navigator.vibrate) navigator.vibrate(10);
  };

  // 3. Map Picker Logic
  const initMap = (lat: number, lng: number) => {
    setIsLocating(true);
    const timeout = setTimeout(() => {
        if (address === 'Fetching location...') {
            setShowRetry(true);
        }
    }, 3000);

    setTimeout(() => {
      if (!mapRef.current) return;

      const center = { lat, lng };
      const map = new google.maps.Map(mapRef.current, {
        zoom: 15,
        center: center,
        disableDefaultUI: true,
        styles: [
            { "featureType": "all", "elementType": "labels.text.fill", "stylers": [{ "color": "#ffffff" }] },
            { "featureType": "all", "elementType": "labels.text.stroke", "stylers": [{ "color": "#000000" }, { "lightness": 13 }] }
        ]
      });

      const marker = new google.maps.Marker({
        position: center,
        map: map,
        draggable: true,
        icon: {
            path: google.maps.SymbolPath.CIRCLE,
            scale: 10,
            fillColor: "#F97316",
            fillOpacity: 1,
            strokeWeight: 2,
            strokeColor: "white"
        }
      });

      const geocoder = new google.maps.Geocoder();

      // Fix: Use any type for pos and parameters to avoid namespace errors
      const updateAddress = (pos: any) => {
        geocoder.geocode({ location: pos }, (results: any, status: any) => {
          if (status === 'OK' && results?.[0]) {
            setAddress(results[0].formatted_address);
            clearTimeout(timeout);
            setIsLocating(false);
          }
        });
      };

      updateAddress(marker.getPosition()!);

      marker.addListener('dragend', () => {
        updateAddress(marker.getPosition()!);
      });

      map.addListener('center_changed', () => {
        marker.setPosition(map.getCenter());
      });

      map.addListener('idle', () => {
        updateAddress(map.getCenter()!);
      });
    }, 100);
  };

  const handleConfirmLocation = () => {
    localStorage.setItem('address_saved', 'true');
    localStorage.setItem('zipright_saved_address', address);
    setStep('contacts');
    if (navigator.vibrate) navigator.vibrate(20);
  };

  // 4. Contacts Step
  const handleSyncContacts = () => {
    localStorage.setItem('zipright_contacts', 'granted');
    setGranted(prev => ({ ...prev, contacts: true }));
    navigate('/home');
  };

  return (
    <div className="relative flex h-screen w-full flex-col bg-black text-white font-display overflow-hidden">

      {/* STEP 1: Permissions List */}
      {step === 'permissions' && (
        <div className="flex-1 flex flex-col p-8 animate-fade-in">
          <div className="mt-12 mb-12">
            <div className="h-14 w-14 rounded-2xl bg-blue-600 flex items-center justify-center shadow-2xl shadow-blue-600/40 mb-6">
                <span className="material-symbols-outlined text-3xl">verified_user</span>
            </div>
            <h1 className="text-4xl font-black tracking-tight leading-tight mb-2">Access Control</h1>
            <p className="text-gray-400 text-base font-medium">ZipRIGHT requires these to function.</p>
          </div>

          <div className="flex flex-col gap-4">
            {/* Camera */}
            <div className="p-5 rounded-3xl bg-white/5 border border-white/10 flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <span className="material-symbols-outlined text-blue-500">camera</span>
                    <div>
                        <p className="font-bold text-sm">Camera</p>
                        <p className="text-[10px] text-gray-500 uppercase tracking-widest">Body Scanning</p>
                    </div>
                </div>
                <button 
                  onClick={handleCamera}
                  className={`px-6 py-2 rounded-full text-[11px] font-black uppercase transition-all ${granted.camera ? 'bg-green-500/20 text-green-500 border border-green-500/30' : 'bg-white text-black'}`}
                >
                  {granted.camera ? 'ALLOWED' : 'ALLOW'}
                </button>
            </div>

            {/* Location */}
            <div className="p-5 rounded-3xl bg-white/5 border border-white/10 flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <span className="material-symbols-outlined text-purple-500">location_on</span>
                    <div>
                        <p className="font-bold text-sm">Location</p>
                        <p className="text-[10px] text-gray-500 uppercase tracking-widest">Local Style Hubs</p>
                    </div>
                </div>
                <button 
                  onClick={handleLocation}
                  className="px-6 py-2 rounded-full text-[11px] font-black uppercase bg-white text-black hover:bg-gray-200"
                >
                  ALLOW
                </button>
            </div>
          </div>
        </div>
      )}

      {/* STEP 2: Map Picker */}
      {step === 'map' && (
        <div className="flex-1 flex flex-col animate-fade-in h-full">
           <div className="relative h-[70%] w-full bg-gray-900">
               <div ref={mapRef} className="h-full w-full"></div>
               {/* Center Pin Overlay (Standard for apps like Swiggy) */}
               <div className="absolute inset-0 pointer-events-none flex items-center justify-center pb-8">
                  <div className="flex flex-col items-center drop-shadow-2xl">
                    <div className="bg-black text-white text-[10px] font-black px-3 py-1 rounded-lg mb-1 animate-bounce">I'm here</div>
                    <span className="material-symbols-outlined text-4xl text-orange-500 filled" style={{ fontVariationSettings: "'FILL' 1" }}>location_on</span>
                  </div>
               </div>

               {/* Search Bar Mockup */}
               <div className="absolute top-6 left-6 right-6 z-10">
                   <div className="bg-white/95 backdrop-blur-md rounded-2xl h-14 flex items-center px-4 shadow-2xl">
                       <span className="material-symbols-outlined text-gray-400 mr-2">search</span>
                       <input className="flex-1 bg-transparent border-none outline-none text-black text-sm font-bold" placeholder="Search for area, street name..." readOnly />
                   </div>
               </div>
           </div>

           {/* Bottom Confirmation Card */}
           <div className="h-[30%] bg-white rounded-t-[2.5rem] p-8 flex flex-col shadow-[0_-20px_50px_rgba(0,0,0,0.3)] animate-slide-up">
              <div className="flex items-start gap-4 mb-8">
                  <div className="h-12 w-12 rounded-full bg-orange-100 flex items-center justify-center shrink-0">
                    <span className="material-symbols-outlined text-orange-600 text-2xl">location_on</span>
                  </div>
                  <div className="flex-1 overflow-hidden">
                    <h3 className="text-xl font-black text-black">Confirming Location</h3>
                    <p className="text-sm text-gray-500 font-bold truncate mt-1">{address}</p>
                    {showRetry && (
                        <button onClick={() => window.location.reload()} className="text-xs font-black text-blue-600 mt-1 uppercase tracking-widest">Retry Connection</button>
                    )}
                  </div>
              </div>
              <button 
                onClick={handleConfirmLocation}
                disabled={isLocating}
                className="w-full h-16 rounded-2xl bg-black text-white font-black text-lg uppercase tracking-widest active:scale-[0.98] transition-all disabled:opacity-50"
              >
                Confirm & Proceed
              </button>
           </div>
        </div>
      )}

      {/* STEP 3: Contacts Popup */}
      {step === 'contacts' && (
        <div className="flex-1 flex flex-col items-center justify-center p-8 animate-fade-in text-center">
            <div className="relative mb-10">
                <div className="absolute inset-0 bg-orange-500/20 rounded-full blur-3xl animate-pulse"></div>
                <div className="relative h-24 w-24 rounded-[2rem] bg-gradient-to-tr from-orange-400 to-orange-600 flex items-center justify-center shadow-2xl">
                    <span className="material-symbols-outlined text-5xl text-white">group</span>
                </div>
            </div>

            <h2 className="text-3xl font-black mb-4">Find Your Friends</h2>
            <p className="text-gray-400 text-base font-medium mb-12 max-w-xs">Sync your contacts to see style picks from people you know.</p>

            <div className="w-full flex flex-col gap-6">
                <button 
                    onClick={handleSyncContacts}
                    className="w-full h-16 rounded-3xl bg-white text-black font-black text-sm uppercase tracking-[0.2em] shadow-2xl active:scale-95"
                >
                    Sync Contacts
                </button>
                <button 
                    onClick={() => navigate('/home')}
                    className="text-sm font-bold text-gray-500 hover:text-white transition-colors"
                >
                    Maybe Later (Skip)
                </button>
            </div>
        </div>
      )}

    </div>
  );
};

