                   <div className="flex items-center gap-4">
                      <div className={`h-12 w-12 rounded-full flex items-center justify-center text-lg font-bold shadow-sm ${member.isPrimary ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-white dark:bg-[#333] text-black dark:text-white'}`}>
