import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const FashionStudio: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  // State
  const [selectedItem, setSelectedItem] = useState(0);
  const [isLiked, setIsLiked] = useState(false);
  const [showToast, setShowToast] = useState(false);

  // Swipe State
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const [touchEnd, setTouchEnd] = useState<number | null>(null);

  // Wardrobe Data
  const [wardrobe, setWardrobe] = useState([
    {
      id: 0,
      name: 'Structured Wool Coat',
      brand: 'The Row',
      price: '₹24,500',
      image: 'https://images.unsplash.com/photo-1591047139829-d91aecb6caea?auto=format&fit=crop&w=800&q=80', // Jacket
      category: 'Outerwear'
    },
    {
      id: 1,
      name: 'Oversized Hoodie',
      brand: 'Fear of God',
      price: '₹12,000',
      image: 'https://images.unsplash.com/photo-1556905055-8f358a7a47b2?auto=format&fit=crop&w=800&q=80', // Hoodie
      category: 'Tops'
    },
    {
      id: 2,
      name: 'Silk Slip Dress',
      brand: 'Anine Bing',
      price: '₹3,500',
      image: 'https://images.unsplash.com/photo-1595777457583-95e059d581b8?auto=format&fit=crop&w=800&q=80', // Dress
      category: 'Dresses'
    },
    {
      id: 3,
      name: 'Denim Jacket',
      brand: 'Levi\'s',
      price: '₹4,500',
      image: 'https://images.unsplash.com/photo-1543076447-215ad9ba6923?auto=format&fit=crop&w=800&q=80', // Denim
      category: 'Outerwear'
    }
  ]);

  const currentItem = wardrobe.find(item => item.id === selectedItem) || wardrobe[0];

  // Handle incoming product from Marketplace
  useEffect(() => {
    if (location.state?.product) {
      const incoming = location.state.product;
      const existingItem = wardrobe.find(item => item.image === incoming.image);

      if (existingItem) {
        setSelectedItem(existingItem.id);
      } else {
        const newId = Date.now();
        const newItem = {
          id: newId,
          name: incoming.title,
          brand: incoming.brand,
          price: incoming.price,
          image: incoming.image,
          category: incoming.category
        };
        setWardrobe(prev => [...prev, newItem]);
        setSelectedItem(newId);
      }
    }
  }, [location.state]);

  // Check Wishlist Status
  useEffect(() => {
    const wishlist = JSON.parse(localStorage.getItem('zipright_wishlist') || '[]');
    // Check if item exists in wishlist (matching by name since IDs might conflict with other pages)
    const exists = wishlist.some((item: any) => item.title === currentItem.name);
    setIsLiked(exists);
  }, [currentItem]);

  // Initialize Camera
  useEffect(() => {
    let localStream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        // Stop any existing tracks before starting a new stream
        if (stream) {
          stream.getTracks().forEach(track => track.stop());
        }

        const mediaStream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: facingMode,
            height: { ideal: 1920 },
            width: { ideal: 1080 }
          }, 
          audio: false 
        });

        localStream = mediaStream;
        setStream(mediaStream);

        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
        }
        setError(null);
      } catch (err) {
        console.error("Camera access denied:", err);
        setError("Please enable camera access to use Virtual Try-On.");
      }
    };

    startCamera();

    return () => {
      if (localStream) {
        localStream.getTracks().forEach(track => track.stop());
      }
    };
  }, [facingMode]);

  const handleBack = () => {
    if (stream) {
        stream.getTracks().forEach(track => track.stop());
    }
    navigate(-1);
  };

  const toggleCamera = () => {
    // Stop current stream to ensure clean switch
    if (stream) {
        stream.getTracks().forEach(track => track.stop());
        setStream(null); 
    }
    setFacingMode(prev => prev === 'user' ? 'environment' : 'user');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const imageUrl = URL.createObjectURL(file);

      const newItem = {
        id: wardrobe.length > 0 ? Math.max(...wardrobe.map(i => i.id)) + 1 : 0,
        name: 'Custom Upload',
        brand: 'My Closet',
        price: '',
        image: imageUrl,
        category: 'Custom'
      };

      setWardrobe(prev => [...prev, newItem]);
      setSelectedItem(newItem.id);
    }
  };

  const handleAddToCart = () => {
      const cart = JSON.parse(localStorage.getItem('zipright_cart') || '[]');

      // Parse price safely (remove currency symbols and commas)
      const priceString = currentItem.price || '0';
      const priceNum = parseFloat(priceString.replace(/[^0-9.]/g, '')) || 0;

      // Check if item exists to update quantity, else add new
      const existingItemIndex = cart.findIndex((item: any) => 
        item.title === currentItem.name && item.brand === currentItem.brand
      );

      let newCart;
      if (existingItemIndex > -1) {
          newCart = [...cart];
          newCart[existingItemIndex].quantity = (newCart[existingItemIndex].quantity || 1) + 1;
      } else {
          const newItem = {
              id: Date.now(),
              title: currentItem.name,
              brand: currentItem.brand,
              price: priceNum,
              size: 'M', // Default size for AR items
              image: currentItem.image,
              quantity: 1
          };
          newCart = [...cart, newItem];
      }

      localStorage.setItem('zipright_cart', JSON.stringify(newCart));

      // Show Toast
      setShowToast(true);
      setTimeout(() => setShowToast(false), 2500);
  };

  const toggleWishlist = () => {
      const wishlist = JSON.parse(localStorage.getItem('zipright_wishlist') || '[]');
      let newWishlist;

      if (isLiked) {
          // Remove
          newWishlist = wishlist.filter((item: any) => item.title !== currentItem.name);
      } else {
          // Add
          const newItem = {
              id: Date.now(),
              title: currentItem.name,
              brand: currentItem.brand,
              price: currentItem.price,
              image: currentItem.image,
              verified: true
          };
          newWishlist = [...wishlist, newItem];
      }

      localStorage.setItem('zipright_wishlist', JSON.stringify(newWishlist));
      setIsLiked(!isLiked);
      if (navigator.vibrate) navigator.vibrate(10);
  };

  // --- Swipe Logic ---
  const handleTouchStart = (e: React.TouchEvent) => {
      setTouchEnd(null); // Reset
      setTouchStart(e.targetTouches[0].clientX);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      setTouchEnd(e.targetTouches[0].clientX);
  };

  const handleTouchEnd = () => {
      if (!touchStart || !touchEnd) return;
      const distance = touchStart - touchEnd;
      const isLeftSwipe = distance > 50;
      const isRightSwipe = distance < -50;

      if (isLeftSwipe) {
          // Next item
          const currentIndex = wardrobe.findIndex(i => i.id === selectedItem);
          const nextIndex = (currentIndex + 1) % wardrobe.length;
          setSelectedItem(wardrobe[nextIndex].id);
      }

      if (isRightSwipe) {
          // Prev item
