import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const PermissionsOnboarding: React.FC = () => {
  const navigate = useNavigate();

  // Workflow steps: 'permissions' -> 'contacts'
  const [step, setStep] = useState<'permissions' | 'contacts'>('permissions');

  // Permissions status
  const [granted, setGranted] = useState({
    camera: localStorage.getItem('zipright_camera') === 'granted',
    location: localStorage.getItem('zipright_location') === 'granted',
    contacts: localStorage.getItem('zipright_contacts') === 'granted'
  });

  // 1. Camera Trigger
  const handleCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      stream.getTracks().forEach(t => t.stop());
      localStorage.setItem('zipright_camera', 'granted');
      setGranted(prev => ({ ...prev, camera: true }));
    } catch (e) {
      console.warn("Camera denied", e);
    }
    if (navigator.vibrate) navigator.vibrate(10);
  };

  // 2. Location Trigger
  const handleLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          localStorage.setItem('zipright_location', 'granted');
          setGranted(prev => ({ ...prev, location: true }));
        },
        (err) => {
          console.warn("Location denied", err);
        }
      );
    }
    if (navigator.vibrate) navigator.vibrate(10);
  };

  // 3. Continue Action
  const handleContinue = () => {
      // Camera is core functionality
      if (!granted.camera) {
          alert("Please allow Camera access to use the Body Scanning features.");
          return;
      }
      // Location is optional, so we proceed regardless
      setStep('contacts');
  };

  // 4. Contacts Step
  const handleSyncContacts = () => {
    localStorage.setItem('zipright_contacts', 'granted');
    setGranted(prev => ({ ...prev, contacts: true }));
    navigate('/home');
  };

  return (
    <div className="relative flex h-screen w-full flex-col bg-black text-white font-display overflow-hidden">

      {/* STEP 1: Permissions List */}
      {step === 'permissions' && (
        <div className="flex-1 flex flex-col p-8 animate-fade-in relative">
          <div className="mt-12 mb-12">
            <div className="h-14 w-14 rounded-2xl bg-blue-600 flex items-center justify-center shadow-2xl shadow-blue-600/40 mb-6">
                <span className="material-symbols-outlined text-3xl">verified_user</span>
            </div>
            <h1 className="text-4xl font-black tracking-tight leading-tight mb-2">Access Control</h1>
            <p className="text-gray-400 text-base font-medium">ZipRIGHT requires these to function.</p>
          </div>

          <div className="flex flex-col gap-4">
            {/* Camera */}
            <div className="p-5 rounded-3xl bg-white/5 border border-white/10 flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <span className="material-symbols-outlined text-blue-500">camera</span>
                    <div>
                        <p className="font-bold text-sm">Camera</p>
                        <p className="text-[10px] text-gray-500 uppercase tracking-widest">Body Scanning</p>
                    </div>
                </div>
                <button 
                  onClick={handleCamera}
                  className={`px-6 py-2 rounded-full text-[11px] font-black uppercase transition-all ${granted.camera ? 'bg-green-500/20 text-green-500 border border-green-500/30' : 'bg-white text-black'}`}
                >
                  {granted.camera ? 'ALLOWED' : 'ALLOW'}
                </button>
            </div>

            {/* Location (Optional) */}
            <div className="p-5 rounded-3xl bg-white/5 border border-white/10 flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <span className="material-symbols-outlined text-purple-500">location_on</span>
                    <div>
                        <p className="font-bold text-sm">Location <span className="text-gray-500 font-normal text-xs">(Optional)</span></p>
                        <p className="text-[10px] text-gray-500 uppercase tracking-widest">Local Style Hubs</p>
                    </div>
                </div>
                <button 
                  onClick={handleLocation}
                  className={`px-6 py-2 rounded-full text-[11px] font-black uppercase transition-all ${granted.location ? 'bg-green-500/20 text-green-500 border border-green-500/30' : 'bg-white text-black hover:bg-gray-200'}`}
                >
                   {granted.location ? 'ALLOWED' : 'ALLOW'}
                </button>
            </div>
          </div>

          {/* Sticky Continue Button */}
          <div className="absolute bottom-8 left-0 right-0 px-8">
            <button 
                onClick={handleContinue}
                className="w-full h-16 rounded-2xl bg-white text-black font-black text-lg uppercase tracking-widest shadow-xl active:scale-[0.98] transition-all flex items-center justify-center gap-2"
            >
                Continue
                <span className="material-symbols-outlined text-xl">arrow_forward</span>
            </button>
          </div>
        </div>
      )}

      {/* STEP 3: Contacts Popup (Now Step 2 essentially) */}
      {step === 'contacts' && (
        <div className="flex-1 flex flex-col items-center justify-center p-8 animate-fade-in text-center">
            <div className="relative mb-10">
                <div className="absolute inset-0 bg-orange-500/20 rounded-full blur-3xl animate-pulse"></div>
                <div className="relative h-24 w-24 rounded-[2rem] bg-gradient-to-tr from-orange-400 to-orange-600 flex items-center justify-center shadow-2xl">
                    <span className="material-symbols-outlined text-5xl text-white">group</span>
                </div>
            </div>

            <h2 className="text-3xl font-black mb-4">Find Your Friends</h2>
            <p className="text-gray-400 text-base font-medium mb-12 max-w-xs">Sync your contacts to see style picks from people you know.</p>

            <div className="w-full flex flex-col gap-6">
                <button 
                    onClick={handleSyncContacts}
                    className="w-full h-16 rounded-3xl bg-white text-black font-black text-sm uppercase tracking-[0.2em] shadow-2xl active:scale-95"
                >
                    Sync Contacts
                </button>
                <button 
                    onClick={() => navigate('/home')}
                    className="text-sm font-bold text-gray-500 hover:text-white transition-colors"
                >
                    Maybe Later (Skip)
                </button>
            </div>
        </div>
      )}

    </div>
  );
};

