  // Mode: 'new' (add secondary), 'edit' (edit existing), 'onboarding' (initial)
  const [mode, setMode] = useState<'new' | 'edit' | 'onboarding'>('onboarding');
  const [editingId, setEditingId] = useState<string | null>(null);

  // Profile Name (New Feature for multiple users)
  const [profileName, setProfileName] = useState('');

  // Profile State
  const [gender, setGender] = useState<'Male' | 'Female' | 'Other'>('Male');
  const [selectedSize, setSelectedSize] = useState('M');
  const [sliderValue, setSliderValue] = useState(2);
  const [selectedBrand, setSelectedBrand] = useState('');
  const [waistSize, setWaistSize] = useState('');
  const [breastSize, setBreastSize] = useState(''); 
  const [braCup, setBraCup] = useState('');
  const [bodyShape, setBodyShape] = useState('');
  const [showFitInfo, setShowFitInfo] = useState(false);
  const [showBodyShapeModal, setShowBodyShapeModal] = useState(false);

  // Height and Weight
  const [heightUnit, setHeightUnit] = useState<'ft' | 'cm'>('ft');
  const [heightFt, setHeightFt] = useState('');
  const [heightIn, setHeightIn] = useState('');
  const [heightCm, setHeightCm] = useState('');
  const [weight, setWeight] = useState('');

  // Initialization
  useEffect(() => {
    const storedMembers = JSON.parse(localStorage.getItem('zipright_members') || '[]');
    const state = location.state || {};

    if (state.mode === 'add') {
        setMode('new');
        setProfileName('');
    } else if (state.mode === 'edit' && state.memberId) {
        setMode('edit');
        setEditingId(state.memberId);
        const member = storedMembers.find((m: any) => m.id === state.memberId);
        if (member) {
            loadMemberData(member);
        }
    } else {
        // Default / Fallback: Check if primary profile exists, if so edit it, else onboarding
        const primary = storedMembers.find((m: any) => m.isPrimary);
        if (primary) {
            setMode('edit');
            setEditingId(primary.id);
            loadMemberData(primary);
        } else {
            setMode('onboarding');
        }
    }
  }, [location.state]);

  const loadMemberData = (member: any) => {
      setProfileName(member.name || '');
      const d = member.fitData || {};
      setGender(d.gender || 'Male');
      setSelectedBrand(d.brand || '');
      setWeight(d.weight || '');
      setHeightUnit(d.heightUnit || 'ft');
      setHeightFt(d.heightFt || '');
      setHeightIn(d.heightIn || '');
      setHeightCm(d.heightCm || '');
      setWaistSize(d.waistSize || '');
