import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const FitProfile: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();

  // Mode: 'new' (add secondary), 'edit' (edit existing), 'onboarding' (initial)
  const [mode, setMode] = useState<'new' | 'edit' | 'onboarding'>('onboarding');
  const [editingId, setEditingId] = useState<string | null>(null);

  // Profile Name (New Feature for multiple users)
  const [profileName, setProfileName] = useState('');

  // Profile State
  const [gender, setGender] = useState<'Male' | 'Female' | 'Other'>('Male');
  const [selectedSize, setSelectedSize] = useState('M');
  const [sliderValue, setSliderValue] = useState(2);
  const [selectedBrand, setSelectedBrand] = useState('');
  const [waistSize, setWaistSize] = useState('');
  const [breastSize, setBreastSize] = useState(''); 
  const [braCup, setBraCup] = useState('');
  const [bodyShape, setBodyShape] = useState('');
  const [showFitInfo, setShowFitInfo] = useState(false);
  const [showBodyShapeModal, setShowBodyShapeModal] = useState(false);

  // Height and Weight
  const [heightUnit, setHeightUnit] = useState<'ft' | 'cm'>('ft');
  const [heightFt, setHeightFt] = useState('');
  const [heightIn, setHeightIn] = useState('');
  const [heightCm, setHeightCm] = useState('');
  const [weight, setWeight] = useState('');

  // Initialization
  useEffect(() => {
    const storedMembers = JSON.parse(localStorage.getItem('zipright_members') || '[]');
    const state = location.state || {};
    const permissionsDone = localStorage.getItem('zipright_permissions_done');

    if (state.mode === 'add') {
        setMode('new');
        setProfileName('');
    } else if (state.mode === 'edit' && state.memberId) {
        setMode('edit');
        setEditingId(state.memberId);
        const member = storedMembers.find((m: any) => m.id === state.memberId);
        if (member) {
            loadMemberData(member);
        }
    } else {
        // Default / Fallback: Check if primary profile exists
        const primary = storedMembers.find((m: any) => m.isPrimary);

        // Even if primary exists, if permissions flow isn't done, treat as onboarding flow (for redirect purposes)
        if (primary && permissionsDone === 'true') {
            setMode('edit');
            setEditingId(primary.id);
            loadMemberData(primary);
        } else if (primary && !permissionsDone) {
             // Primary exists but flow incomplete
             setMode('onboarding'); // Logic will handle saving correctly to not dup, but redirect to permissions
             setEditingId(primary.id);
             loadMemberData(primary);
        } else {
            setMode('onboarding');
        }
    }
  }, [location.state]);

  const loadMemberData = (member: any) => {
      setProfileName(member.name || '');
      const d = member.fitData || {};
      setGender(d.gender || 'Male');
      setSelectedBrand(d.brand || '');
      setWeight(d.weight || '');
      setHeightUnit(d.heightUnit || 'ft');
      setHeightFt(d.heightFt || '');
      setHeightIn(d.heightIn || '');
      setHeightCm(d.heightCm || '');
      setWaistSize(d.waistSize || '');
      setBodyShape(d.bodyShape || '');
      setSelectedSize(d.topSize || 'M');
      setSliderValue(d.fitPreference || 2);
      setBreastSize(d.breastSize || '');
      setBraCup(d.braCup || '');
  };

  // Form Validation
  const isHeightValid = heightUnit === 'cm' 
    ? heightCm.trim() !== '' 
    : (heightFt.trim() !== '' && heightIn.trim() !== '');

  const isWeightValid = weight.trim() !== '';
  const isBodyShapeValid = bodyShape !== '';

  // Profile Name is mandatory if creating a NEW profile that isn't the primary one during onboarding
  const isNameValid = mode === 'new' ? profileName.trim().length > 0 : true;

  // Breast size & Cup is mandatory ONLY if gender is Female
  const isBreastSizeValid = gender === 'Female' ? (breastSize.trim() !== '' && braCup !== '') : true;

  // Brand and measurement fields are mandatory
  const isFormValid = isNameValid && selectedBrand !== '' && isHeightValid && isWeightValid && isBodyShapeValid && isBreastSizeValid;

  // Helper to handle non-negative number inputs
  const handleNumericInput = (setter: (val: string) => void) => (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val === '') {
      setter(val);
      return;
    }
    const num = parseFloat(val);
    if (!isNaN(num) && num >= 0) {
      setter(val);
    }
  };

