import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

// Extend window object for Google API
declare global {
  interface Window {
    google: any;
  }
}

/** 
 * IMPORTANT: Replace this with your actual Client ID from Google Cloud Console 
 * Ensure your origin (e.g., http://localhost:xxxx) is in the "Authorized JavaScript origins" list.
 */
const GOOGLE_CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com';

const Welcome: React.FC = () => {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(false);
  const [tokenClient, setTokenClient] = useState<any>(null);

  useEffect(() => {
    const initializeGoogle = () => {
      if (window.google && window.google.accounts) {
        try {
          const client = window.google.accounts.oauth2.initTokenClient({
            client_id: GOOGLE_CLIENT_ID,
            scope: 'https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/userinfo.email',
            callback: (response: any) => handleGoogleResponse(response),
          });
          setTokenClient(client);
        } catch (err) {
          console.error("GIS initialization error:", err);
        }
      }
    };

    // Load Google script check
    if (window.google) {
      initializeGoogle();
    } else {
      const interval = setInterval(() => {
        if (window.google) {
          initializeGoogle();
          clearInterval(interval);
        }
      }, 100);
      return () => clearInterval(interval);
    }
  }, []);

  const handleGoogleResponse = async (tokenResponse: any) => {
    if (tokenResponse.error) {
      console.error('Google Auth Error:', tokenResponse);
      setIsLoading(false);
      return;
    }

    try {
      const userInfoResponse = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
        headers: { Authorization: `Bearer ${tokenResponse.access_token}` },
      });

      if (!userInfoResponse.ok) {
        throw new Error('Failed to fetch user info');
      }

      const googleUser = await userInfoResponse.json();

      const appUser = {
        id: googleUser.sub,
        firstName: googleUser.given_name,
        lastName: googleUser.family_name,
        email: googleUser.email,
        photoUrl: googleUser.picture,
        token: tokenResponse.access_token,
        provider: 'google'
      };

      localStorage.setItem('zipright_user', JSON.stringify(appUser));

      // Create a default member profile for the user
      const storedMembers = localStorage.getItem('zipright_members');
      let members = storedMembers ? JSON.parse(storedMembers) : [];

      if (!members.some((m: any) => m.isPrimary)) {
        const newProfile = {
          id: googleUser.sub,
          name: googleUser.name || 'My Fits',
          isPrimary: true,
          fitData: {
            brand: 'Nike',
            topSize: 'M',
            waistSize: '32',
            heightUnit: 'ft',
            heightFt: '5',
            heightIn: '10',
            weight: '75',
            fitPreference: 2
          }
        };
        members = [newProfile, ...members];
        localStorage.setItem('zipright_members', JSON.stringify(members));
      }

      setIsLoading(false);
      navigate('/how-it-works');
    } catch (err) {
      console.error("Token exchange failed:", err);
      setIsLoading(false);
    }
  };

  const handleGoogleLogin = () => {
    if (tokenClient) {
      setIsLoading(true);
      // prompt: 'select_account' ensures the account selector is always shown
      tokenClient.requestAccessToken({ prompt: 'select_account' });
    } else {
      alert("Google Login is still initializing. Please try again in a moment.");
    }
  };

  const handlePhoneLogin = () => {
    navigate('/login', { state: { method: 'phone' } });
  };

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col bg-[#f7f7f7] dark:bg-[#121212] overflow-x-hidden font-display">
      {/* Header */}
      <div className="flex items-center px-6 py-6 pt-8 justify-between z-10">
        <div className="flex items-center gap-2">
          <span className="material-symbols-outlined text-black dark:text-white" style={{ fontSize: '28px' }}>checkroom</span>
          <span className="text-black dark:text-white text-xl font-bold tracking-tight">ZipRIGHT</span>
        </div>
        <button className="h-10 w-10 flex items-center justify-center rounded-full bg-black/5 dark:bg-white/5">
          <span className="material-symbols-outlined text-black dark:text-white opacity-60">more_horiz</span>
        </button>
      </div>

      <div className="flex-1 flex flex-col items-center justify-start w-full">
        {/* Hero Section */}
        <div className="w-full px-4 pt-2 pb-6">
          <div className="relative w-full aspect-[4/5] rounded-[2.5rem] overflow-hidden shadow-2xl group border border-black/5 dark:border-white/5">
            <div 
              className="absolute inset-0 bg-cover bg-center transition-transform duration-1000 group-hover:scale-110" 
              style={{ backgroundImage: "url('https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?q=80&w=1000&auto=format&fit=crop')" }}
            >
              <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-black/30 dark:to-black/80"></div>
            </div>
          </div>
        </div>

        {/* Text Content */}
        <div className="flex flex-col items-center px-6 text-center">
          <h1 className="text-black dark:text-white text-3xl font-black tracking-tight leading-none mb-4">
            Shop Smarter.<br />Fit Better.
          </h1>
          <p className="text-gray-500 dark:text-gray-400 text-base font-medium leading-relaxed max-w-[260px]">
            AI powered size recommendations for every brand you love.
          </p>
        </div>
      </div>

      {/* Action Buttons Section */}
      <div className="w-full px-6 py-8 pb-10 mt-auto">
        <div className="flex flex-col gap-3">
          {/* Google Button */}
          <button 
            onClick={handleGoogleLogin} 
            disabled={isLoading}
            className="group relative flex h-14 w-full items-center justify-center rounded-2xl bg-white dark:bg-[#1C1C1E] border border-gray-200 dark:border-white/10 shadow-sm transition-all hover:bg-gray-50 dark:hover:bg-[#252525] active:scale-[0.98] disabled:opacity-80"
          >
            {isLoading ? (
              <div className="flex items-center gap-3">
                <div className="h-5 w-5 border-2 border-black dark:border-white border-t-transparent rounded-full animate-spin"></div>
                <span className="font-bold text-black dark:text-white">Connecting...</span>
              </div>
            ) : (
              <>
                <img src="https://www.svgrepo.com/show/475656/google-color.svg" className="h-5 w-5 absolute left-6" alt="G" />
                <span className="font-bold text-black dark:text-white">Continue with Google</span>
              </>
            )}
          </button>

          {/* Phone Button */}
          <button 
            onClick={handlePhoneLogin}
            disabled={isLoading} 
            className="relative flex h-14 w-full items-center justify-center rounded-2xl bg-white dark:bg-[#1C1C1E] border border-gray-200 dark:border-white/10 shadow-sm transition-all hover:bg-gray-50 dark:hover:bg-[#252525] active:scale-[0.98]"
          >
            <span className="material-symbols-outlined text-black dark:text-white absolute left-6" style={{ fontSize: '20px' }}>call</span>
            <span className="font-bold text-black dark:text-white">Continue with Phone</span>
          </button>
        </div>

        <p className="text-[11px] text-center text-gray-400 dark:text-gray-500 mt-6 font-medium">
          By continuing, you agree to our 
          <button onClick={() => navigate('/terms-of-use')} className="text-black dark:text-white underline font-bold mx-1 hover:text-blue-500 transition-colors">Terms</button> 
          & 
          <button onClick={() => navigate('/privacy-policy')} className="text-black dark:text-white underline font-bold mx-1 hover:text-blue-500 transition-colors">Privacy Policy</button>
        </p>
      </div>
    </div>
  );
};

