import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { GoogleGenAI } from "@google/genai";

interface Message {
  id: string;
  text: string;
  sender: 'user' | 'ai';
  timestamp: Date;
}

const StylistChat: React.FC = () => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      text: "Hi! I'm your personal AI stylist. I know your fit profile and preferences. Ask me anything about style, outfits, or what to wear for an event!",
      sender: 'ai',
      timestamp: new Date()
    }
  ]);

  // Quick suggestions that appear on the user's side
  const [suggestions, setSuggestions] = useState<string[]>([
      "what can you do",
      "Find me an outfit for a date",
      "What's trending now?"
  ]);

  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping, suggestions]);

  const handleSend = async (text: string = inputText) => {
    if (!text.trim()) return;

    // Clear suggestions after first interaction
    if (suggestions.length > 0) setSuggestions([]);

    const userMsg: Message = {
      id: Date.now().toString(),
      text: text,
      sender: 'user',
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsTyping(true);

    if (navigator.vibrate) navigator.vibrate(10);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // Retrieve context
        const userProfile = localStorage.getItem('zipright_members');
        const context = userProfile 
            ? `User Profile Context: ${userProfile}. You are a helpful fashion stylist for ZipRIGHT app. Keep answers short, trendy and helpful.` 
            : `You are a helpful fashion stylist for ZipRIGHT app. Keep answers short and stylish.`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: text,
            config: {
                systemInstruction: context,
            }
        });

        const aiMsg: Message = {
            id: (Date.now() + 1).toString(),
            text: response.text || "I'm having trouble thinking of a style tip right now. Try again?",
            sender: 'ai',
            timestamp: new Date()
        };

        setIsTyping(false);
        setMessages(prev => [...prev, aiMsg]);
        if (navigator.vibrate) navigator.vibrate([10, 30, 10]);

    } catch (error) {
        console.error("AI Error", error);
        setIsTyping(false);
        setMessages(prev => [...prev, {
            id: Date.now().toString(),
            text: "My fashion senses are tingling... but I can't connect right now. Please try again later.",
            sender: 'ai',
            timestamp: new Date()
        }]);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSend();
  };

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col bg-[#050505] font-display overflow-hidden text-white">
      {/* Header */}
      <div className="sticky top-0 z-50 flex items-center gap-4 px-6 py-4 bg-[#050505]/95 backdrop-blur-xl border-b border-white/5">
        <button onClick={() => navigate(-1)} className="flex items-center justify-center h-10 w-10 -ml-2 rounded-full hover:bg-white/10 active:scale-95 transition-all">
          <span className="material-symbols-outlined text-white text-[24px]">arrow_back</span>
        </button>
        <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-full bg-gradient-to-br from-[#6366f1] to-[#a855f7] flex items-center justify-center shadow-[0_0_15px_rgba(168,85,247,0.4)]">
                <span className="material-symbols-outlined text-white text-[20px]">auto_awesome</span>
            </div>
            <div>
                <h2 className="text-base font-bold text-white leading-tight">AI Stylist</h2>
                <div className="flex items-center gap-1.5 mt-0.5">
                    <div className="h-1.5 w-1.5 rounded-full bg-[#22c55e] shadow-[0_0_8px_#22c55e]"></div>
                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Online</p>
                </div>
            </div>
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto px-4 pt-6 pb-28 no-scrollbar scroll-smooth">
        <div className="flex flex-col gap-6">
            <div className="flex justify-center mb-2">
                <span className="text-[10px] font-bold text-gray-600 uppercase tracking-[0.2em]">Today</span>
            </div>

            {messages.map((msg) => (
                <div key={msg.id} className={`flex w-full animate-in slide-in-from-bottom-2 duration-300 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] p-4 text-[15px] font-medium leading-relaxed shadow-sm relative group ${
                        msg.sender === 'user' 
                        ? 'bg-white text-black rounded-2xl rounded-tr-sm' 
                        : 'bg-[#1C1C1E] text-gray-100 rounded-2xl rounded-tl-sm border border-white/5'
                    }`}>
                        {msg.text}
                    </div>
                </div>
            ))}

            {/* Quick Suggestions (Rendered as interactive user bubbles) */}
            {suggestions.length > 0 && !isTyping && (
                <div className="flex flex-col items-end gap-2 animate-in fade-in slide-in-from-bottom-2 duration-500 delay-100">
                    {suggestions.map((suggestion, idx) => (
                        <button 
                            key={idx}
                            onClick={() => handleSend(suggestion)}
                            className="bg-white text-black px-5 py-3 rounded-2xl rounded-tr-sm text-[15px] font-medium shadow-md hover:scale-[1.02] active:scale-95 transition-all text-left max-w-[85%]"
                        >
                            {suggestion}
                        </button>
                    ))}
                </div>
            )}

            {isTyping && (
                <div className="flex justify-start animate-in fade-in zoom-in-95 duration-300">
                    <div className="bg-[#1C1C1E] px-4 py-4 rounded-2xl rounded-tl-sm border border-white/5 flex gap-1.5 items-center w-fit h-12">
                        <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                        <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                        <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce"></div>
                    </div>
                </div>
            )}
            <div ref={messagesEndRef} className="h-4" />
        </div>
      </div>

      {/* Input Area */}
      <div className="fixed bottom-0 left-0 w-full bg-gradient-to-t from-black via-black/90 to-transparent p-4 pb-8 max-w-md mx-auto right-0 pt-12">
          <div className="flex items-center gap-2 bg-[#1C1C1E] p-1.5 pl-5 pr-1.5 rounded-[2rem] border border-white/10 shadow-2xl ring-1 ring-white/5 focus-within:ring-white/20 transition-all">
              <input 
                type="text" 
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyDown={handleKeyPress}
                placeholder="Ask for advice..."
                className="flex-1 bg-transparent border-none outline-none h-11 text-white placeholder:text-gray-500 text-[15px] font-medium"
              />
              <button 
                onClick={() => handleSend()}
                disabled={!inputText.trim()}
                className={`h-11 w-11 flex items-center justify-center rounded-full transition-all active:scale-90 ${
                    inputText.trim() 
                    ? 'bg-white text-black shadow-[0_0_15px_rgba(255,255,255,0.3)]' 
                    : 'bg-white/5 text-gray-600'
                }`}
              >
                  <span className="material-symbols-outlined text-[20px] ml-0.5">send</span>
              </button>
          </div>
      </div>
    </div>
  );
};

