    if (currentTotal >= 10) {
        setToastMessage('Cart limit reached (Max 10)');
        setIsError(true);
        setShowToast(true);
        setTimeout(() => setShowToast(false), 2500);
        return false;
    }

    const priceNum = typeof displayProduct.price === 'string'
            ? parseFloat(displayProduct.price.replace(/[^0-9.-]+/g,""))
            : displayProduct.price;

    const size = isClothing ? recommendedSize : 'One Size';

    // Check if item exists to group it
    const existingItemIndex = existingCart.findIndex((item: any) => 
        item.title === displayProduct.title && 
        item.brand === displayProduct.brand && 
        item.size === size
    );

    let newCart;
    if (existingItemIndex > -1) {
        newCart = [...existingCart];
        newCart[existingItemIndex].quantity = (newCart[existingItemIndex].quantity || 1) + 1;
    } else {
        const cartItem = {
            id: Date.now(),
            title: displayProduct.title,
            brand: displayProduct.brand,
            price: priceNum,
            size: size,
            image: displayProduct.image,
            quantity: 1
        };
        newCart = [...existingCart, cartItem];
    }

    localStorage.setItem('zipright_cart', JSON.stringify(newCart));

    // Update badge count
    setCartCount(newCart.reduce((acc: any, item: any) => acc + (item.quantity || 1), 0));

    if (!silent) {
