import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

interface Address {
  id: string;
  type: 'Home' | 'Work' | 'Other';
  name: string;
  phone: string;
  street: string;
  city: string;
  state: string;
  zip: string;
  isDefault: boolean;
}

const SelectAddress: React.FC = () => {
  const navigate = useNavigate();
  const [selectedAddressId, setSelectedAddressId] = useState<string | null>(null);

  // Load addresses from local storage (synced with Settings)
  const [addresses, setAddresses] = useState<Address[]>(() => {
    const stored = localStorage.getItem('zipright_addresses');
    const parsed = stored ? JSON.parse(stored) : [];
    return parsed;
  });

  useEffect(() => {
      // Default to the first address if none selected
      if (!selectedAddressId && addresses.length > 0) {
          const defaultAddr = addresses.find(a => a.isDefault) || addresses[0];
          setSelectedAddressId(defaultAddr.id);
      }
  }, [addresses]);

  const handleBack = () => {
    if (window.history.state && window.history.state.idx > 0) {
        navigate(-1);
    } else {
        navigate('/cart');
    }
  };

  const handleContinue = () => {
      if (selectedAddressId) {
          const selected = addresses.find(a => a.id === selectedAddressId);
          // Can pass address via state if needed, or just persist selection
          navigate('/checkout/payment', { state: { address: selected } });
      }
  };

  const handleAddNew = () => {
      // Navigate to Settings to add address, maybe with a return url param in future
      // For now, simpler to just go to Settings
      navigate('/settings');
  };

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col bg-[#F2F2F7] dark:bg-[#000000] text-black dark:text-white font-display overflow-hidden">

      {/* Header */}
      <div className="sticky top-0 z-50 flex items-center justify-between px-6 py-4 bg-[#F2F2F7]/80 dark:bg-black/80 backdrop-blur-xl border-b border-black/5 dark:border-white/5">
        <button onClick={handleBack} className="flex items-center justify-center h-10 w-10 rounded-full bg-gray-200/50 dark:bg-[#1C1C1E] active:scale-95 transition-all">
          <span className="material-symbols-outlined text-black dark:text-white">arrow_back</span>
        </button>
        <h2 className="text-lg font-bold">Select Address</h2>
        <div className="w-10"></div>
      </div>

      <div className="flex-1 overflow-y-auto px-6 pt-4 pb-32 no-scrollbar">
          <div className="flex flex-col gap-4">
              {addresses.map((addr) => (
                  <div 
                    key={addr.id} 
                    onClick={() => setSelectedAddressId(addr.id)}
                    className={`flex flex-col p-5 rounded-3xl border transition-all cursor-pointer relative ${selectedAddressId === addr.id ? 'bg-white dark:bg-[#1C1C1E] border-black dark:border-white ring-1 ring-black dark:ring-white' : 'bg-white dark:bg-[#1C1C1E] border-transparent opacity-80 hover:opacity-100'}`}
                  >
                        {addr.isDefault && (
                             <div className="absolute top-4 right-4 bg-gray-200 dark:bg-white/10 text-black dark:text-white text-[10px] font-bold px-2 py-1 rounded-md uppercase tracking-wide">Default</div>
                         )}
                         <div className="flex items-start gap-4">
                             <div className={`h-6 w-6 rounded-full border-2 flex items-center justify-center mt-1 ${selectedAddressId === addr.id ? 'border-black dark:border-white' : 'border-gray-300 dark:border-gray-600'}`}>
                                 {selectedAddressId === addr.id && <div className="h-3 w-3 rounded-full bg-black dark:bg-white"></div>}
                             </div>
                             <div className="flex-1">
                                 <div className="flex items-center gap-2 mb-1">
                                    <span className="font-bold text-base">{addr.type}</span>
                                 </div>
                                 <h3 className="text-sm font-bold text-gray-800 dark:text-gray-200">{addr.name}</h3>
                                 <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 leading-relaxed">
                                     {addr.street}, {addr.city}, {addr.state} - {addr.zip}
                                 </p>
                                 <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 font-medium">Mobile: {addr.phone}</p>
                             </div>
                         </div>
                  </div>
              ))}

              <button 
                onClick={handleAddNew}
                className="flex items-center justify-center gap-2 p-5 rounded-3xl border-2 border-dashed border-gray-300 dark:border-gray-700 hover:border-black dark:hover:border-white text-gray-500 hover:text-black dark:text-gray-400 dark:hover:text-white font-bold transition-all"
              >
                 <span className="material-symbols-outlined">add</span>
                 <span>Add New Address</span>
              </button>
          </div>
      </div>

      <div className="fixed bottom-0 left-0 w-full bg-white dark:bg-[#101010] border-t border-gray-200 dark:border-white/10 rounded-t-[2rem] shadow-[0_-10px_40px_rgba(0,0,0,0.2)] p-6 z-40 pb-10 max-w-md mx-auto right-0">
         <button 
            onClick={handleContinue}
            disabled={!selectedAddressId}
            className="w-full h-14 rounded-2xl bg-black dark:bg-white text-white dark:text-black font-bold text-lg shadow-xl hover:scale-[1.01] active:scale-[0.99] transition-all flex items-center justify-center gap-2 cursor-pointer disabled:opacity-50"
         >
            Deliver Here
            <span className="material-symbols-outlined text-[20px]">arrow_forward</span>
         </button>
      </div>
    </div>
  );
};

