import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const SelectPayment: React.FC = () => {
  const navigate = useNavigate();
  const [selectedMethod, setSelectedMethod] = useState<string>('gpay');
  const [isProcessing, setIsProcessing] = useState(false);

  // Calculate Total from Cart
  const [cartTotal, setCartTotal] = useState(0);

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('zipright_cart') || '[]');
    const subtotal = cart.reduce((sum: number, item: any) => sum + (item.price * (item.quantity || 1)), 0);
    const shipping = cart.length > 0 ? 25 : 0;
    setCartTotal(subtotal + shipping);
  }, []);

  const handleBack = () => {
    if (window.history.state && window.history.state.idx > 0) {
        navigate(-1);
    } else {
        navigate('/checkout/address');
    }
  };

  const handlePay = () => {
      setIsProcessing(true);

      // Simulate Payment Processing
      setTimeout(() => {
          // Clear Cart
          localStorage.removeItem('zipright_cart');
          setIsProcessing(false);
          navigate('/success');
      }, 2000);
  };

  const methods = [
      { id: 'gpay', name: 'Google Pay', icon: 'account_balance_wallet', type: 'UPI' },
      { id: 'card', name: 'Credit/Debit Card', icon: 'credit_card', type: 'Card' },
      { id: 'netbanking', name: 'Net Banking', icon: 'account_balance', type: 'Bank' },
      { id: 'cod', name: 'Cash on Delivery', icon: 'payments', type: 'Cash' },
  ];

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col bg-[#F2F2F7] dark:bg-[#000000] text-black dark:text-white font-display overflow-hidden">

      {/* Header */}
      <div className="sticky top-0 z-50 flex items-center justify-between px-6 py-4 bg-[#F2F2F7]/80 dark:bg-black/80 backdrop-blur-xl border-b border-black/5 dark:border-white/5">
        <button onClick={handleBack} className="flex items-center justify-center h-10 w-10 rounded-full bg-gray-200/50 dark:bg-[#1C1C1E] active:scale-95 transition-all">
          <span className="material-symbols-outlined text-black dark:text-white">arrow_back</span>
        </button>
        <h2 className="text-lg font-bold">Payment Method</h2>
        <div className="w-10"></div>
      </div>

      <div className="flex-1 overflow-y-auto px-6 pt-4 pb-32 no-scrollbar">
          <div className="flex flex-col gap-2 mb-6">
              <p className="text-sm font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wide ml-1">Total Amount</p>
              <h1 className="text-4xl font-black">${cartTotal.toLocaleString()}</h1>
          </div>

          <div className="flex flex-col gap-4">
              {methods.map((method) => (
                  <div 
                    key={method.id} 
                    onClick={() => setSelectedMethod(method.id)}
                    className={`flex items-center gap-4 p-5 rounded-3xl border transition-all cursor-pointer relative ${selectedMethod === method.id ? 'bg-white dark:bg-[#1C1C1E] border-black dark:border-white ring-1 ring-black dark:ring-white' : 'bg-white dark:bg-[#1C1C1E] border-transparent opacity-80 hover:opacity-100'}`}
                  >
                       <div className="h-12 w-12 rounded-full bg-gray-100 dark:bg-white/5 flex items-center justify-center shrink-0">
                           <span className="material-symbols-outlined text-black dark:text-white">{method.icon}</span>
                       </div>
                       <div className="flex-1">
                           <h3 className="text-base font-bold">{method.name}</h3>
                           <p className="text-xs text-gray-500 dark:text-gray-400 font-medium">{method.type}</p>
                       </div>
                       <div className={`h-6 w-6 rounded-full border-2 flex items-center justify-center ${selectedMethod === method.id ? 'border-black dark:border-white' : 'border-gray-300 dark:border-gray-600'}`}>
                            {selectedMethod === method.id && <div className="h-3 w-3 rounded-full bg-black dark:bg-white"></div>}
                       </div>
                  </div>
              ))}
          </div>

          {/* Secure Badge */}
          <div className="mt-8 flex items-center justify-center gap-2 text-gray-400">
              <span className="material-symbols-outlined text-lg">lock</span>
              <span className="text-xs font-bold uppercase tracking-wide">100% Secure Payment</span>
          </div>
      </div>

      <div className="fixed bottom-0 left-0 w-full bg-white dark:bg-[#101010] border-t border-gray-200 dark:border-white/10 rounded-t-[2rem] shadow-[0_-10px_40px_rgba(0,0,0,0.2)] p-6 z-40 pb-10 max-w-md mx-auto right-0">
         <button 
            onClick={handlePay}
            disabled={isProcessing}
            className="w-full h-14 rounded-2xl bg-black dark:bg-white text-white dark:text-black font-bold text-lg shadow-xl hover:scale-[1.01] active:scale-[0.99] transition-all flex items-center justify-center gap-2 cursor-pointer disabled:opacity-70"
         >
            {isProcessing ? (
                <div className="flex items-center gap-2">
                    <div className="h-5 w-5 border-2 border-white dark:border-black border-t-transparent rounded-full animate-spin"></div>
                    <span>Processing Payment...</span>
                </div>
            ) : (
                <>
                    Pay Now
                    <span className="material-symbols-outlined text-[20px]">payments</span>
                </>
            )}
         </button>
      </div>
    </div>
  );
};

