const App: React.FC = () => {
  // System Adaptable Theme Logic
  useEffect(() => {
    // 1. Check for manual override first
    const storedTheme = localStorage.getItem('zipright_theme');

    const applyTheme = (theme: 'dark' | 'light') => {
      if (theme === 'dark') {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    };

    if (storedTheme) {
      applyTheme(storedTheme as 'dark' | 'light');
    } else {
      // 2. If no override, use System Preference
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      applyTheme(mediaQuery.matches ? 'dark' : 'light');

      // 3. Listen for system changes
      const handleChange = (e: MediaQueryListEvent) => {
        // Only react if user hasn't set a manual preference
        if (!localStorage.getItem('zipright_theme')) {
          applyTheme(e.matches ? 'dark' : 'light');
        }
      };

      mediaQuery.addEventListener('change', handleChange);
      return () => mediaQuery.removeEventListener('change', handleChange);
    }
  }, []);

  return (
    <HashRouter>
      <div className="max-w-md mx-auto min-h-screen bg-bg-light dark:bg-bg-dark relative overflow-hidden shadow-2xl transition-colors duration-300">
        <Routes>
          <Route path="/" element={<Splash />} />
          <Route path="/welcome" element={<Welcome />} />
          <Route path="/login" element={<Login />} />
          <Route path="/how-it-works" element={<HowItWorks />} />
          <Route path="/fit-profile" element={<FitProfile />} />
          <Route path="/success" element={<Success />} />
          <Route path="/permissions-onboarding" element={<PermissionsOnboarding />} />
          <Route path="/home" element={<Home />} />
          <Route path="/add-product" element={<AddProduct />} />
          <Route path="/recommendation" element={<Recommendation />} />
          <Route path="/marketplace" element={<Marketplace />} />
          <Route path="/settings" element={<Settings />} />
          <Route path="/avatar-intro" element={<AvatarIntro />} />
          <Route path="/avatar-view" element={<AvatarView />} />
          <Route path="/fashion-studio" element={<FashionStudio />} />
          <Route path="/cart" element={<Cart />} />
          <Route path="/wishlist" element={<Wishlist />} />
          <Route path="/recent-scans" element={<RecentScans />} />
          <Route path="/order-history" element={<OrderHistory />} />
          <Route path="/stylist" element={<StylistChat />} />

          {/* Checkout Flow */}
          <Route path="/checkout/address" element={<SelectAddress />} />
          <Route path="/checkout/payment" element={<SelectPayment />} />

          {/* Info Pages */}
          <Route path="/faqs" element={<FAQs />} />
