      if (navigator.vibrate) navigator.vibrate(20);
  };

  const addToCart = (item: any) => {
    const existingCart = JSON.parse(localStorage.getItem('zipright_cart') || '[]');
    const priceNum = typeof item.price === 'string'
            ? parseFloat(item.price.replace(/[^0-9.-]+/g,""))
            : item.price;

    const cartItem = {
        id: Date.now(),
        title: item.title,
        brand: item.brand,
        price: priceNum,
        size: 'M',
        image: item.image,
        quantity: 1
    };

    const newCart = [...existingCart, cartItem];
    localStorage.setItem('zipright_cart', JSON.stringify(newCart));
    if (navigator.vibrate) navigator.vibrate(50);

    alert('Added to Cart');
  };

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col bg-[#F2F2F7] dark:bg-[#000000] text-black dark:text-white font-display overflow-hidden">

      {/* Header */}
      <div className="sticky top-0 z-50 flex items-center justify-between px-6 py-4 bg-[#F2F2F7]/80 dark:bg-black/80 backdrop-blur-xl border-b border-black/5 dark:border-white/5 transition-all duration-300">
