          <span className="material-symbols-outlined text-black dark:text-white">arrow_back</span>
        </button>
        <h2 className="text-lg font-bold text-black dark:text-white">Wishlist</h2>
        <div className="w-10"></div>
      </div>

      {/* Grid Content */}
      <div className="flex-1 overflow-y-auto px-6 pt-4 pb-10 no-scrollbar">
        {isLoading ? (
            /* Skeleton Loading State */
            <div className="grid grid-cols-2 gap-x-4 gap-y-6">
                {[...Array(4)].map((_, i) => (
                    <div key={i} className="flex flex-col gap-3 animate-pulse">
                        <div className="w-full aspect-[3/4] rounded-[1.5rem] bg-gray-200 dark:bg-gray-800"></div>
                        <div className="px-1 space-y-2">
                            <div className="h-3 w-3/4 bg-gray-200 dark:bg-gray-800 rounded"></div>
                            <div className="h-3 w-1/2 bg-gray-200 dark:bg-gray-800 rounded"></div>
                        </div>
                    </div>
                ))}
            </div>
        ) : wishlistItems.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-[50vh] opacity-50">
                <span className="material-symbols-outlined text-4xl mb-2">favorite_border</span>
                <p className="font-bold">Your wishlist is empty</p>
            </div>
        ) : (
            <div className="grid grid-cols-2 gap-x-4 gap-y-6">
                {wishlistItems.map((item) => (
                    <div key={item.id} className="flex flex-col gap-3 group">
                        <div className="relative w-full aspect-[3/4] overflow-hidden rounded-[1.5rem] bg-gray-100 dark:bg-[#1C1C1E] shadow-sm ring-1 ring-black/5 dark:ring-white/10">
                            <div 
                            className="w-full h-full bg-center bg-no-repeat bg-cover group-hover:scale-105 transition-transform duration-700"
                            style={{ backgroundImage: `url("${item.image}")` }}
                            ></div>
                            <button 
                                onClick={() => removeFromWishlist(item.id)}
                                className="absolute top-3 right-3 h-8 w-8 rounded-full bg-red-500 text-white flex items-center justify-center transition-transform active:scale-90 shadow-md z-10"
                            >
                                <span className="material-symbols-outlined text-[18px] filled" style={{ fontVariationSettings: "'FILL' 1" }}>favorite</span>
                            </button>

                            <div className="absolute bottom-3 right-3 left-3">
