                                    onClick={() => addToCart(item)}
                                    className="w-full h-9 rounded-xl bg-white/90 dark:bg-black/80 backdrop-blur-md flex items-center justify-center gap-1.5 shadow-sm active:scale-95 transition-all hover:bg-white dark:hover:bg-black cursor-pointer"
                                >
