          setMembers(JSON.parse(storedMembers));
        } else {
          setMembers([{ id: '1', name: 'My Fits', isPrimary: true }]);
        }
    } catch (e) {
        console.error("Error parsing members", e);
        setMembers([{ id: '1', name: 'My Fits', isPrimary: true }]);
    }

    try {
        const cart = JSON.parse(localStorage.getItem('zipright_cart') || '[]');
        const count = cart.reduce((acc: number, item: any) => acc + (item.quantity || 1), 0);
        setCartCount(count);
    } catch (e) {
        console.error("Error parsing cart", e);
        setCartCount(0);
    }

    return () => clearTimeout(timer);
  }, []);

  const handleProductClick = (product: any) => {
    const defaultMember = members.find(m => m.isPrimary) || members[0];
    navigate('/recommendation', { state: { memberId: defaultMember.id, product: product, source: 'marketplace' } });
  };

  // Filter Logic based on Active Tab
  const filteredProducts = products.filter(p => {
      if (activeTab === 'All') return true;
      if (activeTab === 'Men') return p.category === 'Men';
      if (activeTab === 'Women') return p.category === 'Women';
      if (activeTab === 'Kids') return p.category === 'Kids';
      return true;
  });

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col bg-white dark:bg-black text-text-light dark:text-white font-display overflow-hidden pb-20">

