                        <span className="absolute -top-1 -right-1 h-4 w-4 bg-myntra rounded-full text-[9px] font-bold flex items-center justify-center text-white">{cartCount}</span>
                    )}
                 </button>
             </div>
         </div>

         {/* Second Row: Toggle (Discover / Marketplace) */}
         <div className="px-4 pb-3">
             <div className="flex p-1 bg-[#F5F5F6] dark:bg-[#1A1A1A] rounded-lg">
                 <button 
                    onClick={() => setViewMode('discover')}
                    className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all ${
                        viewMode === 'discover' 
                        ? 'bg-white dark:bg-[#333] text-black dark:text-white shadow-sm' 
                        : 'text-gray-500'
                    }`}
                 >
                     Discover
                 </button>
                 <button 
                    onClick={() => setViewMode('marketplace')}
                    className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all ${
                        viewMode === 'marketplace' 
                        ? 'bg-white dark:bg-[#333] text-black dark:text-white shadow-sm' 
                        : 'text-gray-500'
                    }`}
                 >
                     Marketplace
                 </button>
             </div>
         </div>

         {/* Third Row: Sticky Horizontal Tabs (Only in Discover Mode) */}
