             <div className="flex px-2 overflow-x-auto no-scrollbar border-t border-gray-50 dark:border-[#1A1A1A]">
                 {tabs.map(tab => (
                     <button
                        key={tab}
                        onClick={() => setActiveTab(tab)}
                        className={`flex-1 min-w-[80px] py-3 text-sm font-bold text-center relative transition-colors ${
                            activeTab === tab 
                            ? 'text-text-light dark:text-white' 
