                  <div className="flex gap-4">
                     <div 
                        className="w-20 h-24 rounded-xl bg-cover bg-center shrink-0 border border-gray-100 dark:border-white/5"
                        style={{ backgroundImage: `url(${order.image})` }}
                    ></div>
                    <div className="flex flex-col flex-1 justify-between py-0.5">
                       <div>
                           <div className="flex justify-between items-start">
                               <h3 className="font-bold text-base leading-tight pr-2 line-clamp-2">{order.title}</h3>
                               <span className="text-sm font-bold">₹{order.price.toLocaleString()}</span>
                           </div>
                           <p className="text-sm text-gray-500 dark:text-gray-400 font-medium">{order.brand}</p>
                       </div>
                       <div className="flex flex-col gap-1">
                           <span className={`text-xs font-bold px-2 py-0.5 rounded-md w-fit ${order.status === 'Delivered' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' : 'bg-gray-100 text-gray-600 dark:bg-white/10 dark:text-gray-400'}`}>
                               {order.status}
                           </span>
                           <span className="text-xs text-gray-400 dark:text-gray-500">{order.date}</span>
                       </div>
                    </div>
                  </div>

                  <div className="h-[1px] bg-gray-100 dark:bg-white/5 w-full"></div>

                  <div className="flex gap-3">
                      <button className="flex-1 h-10 rounded-xl border border-gray-200 dark:border-white/10 text-sm font-bold text-black dark:text-white hover:bg-gray-50 dark:hover:bg-white/5 transition-colors">
                          Track Order
                      </button>
                      <button 
                        onClick={() => handleBuyAgain(order)}
                        className="flex-1 h-10 rounded-xl bg-black dark:bg-white text-white dark:text-black text-sm font-bold hover:opacity-90 transition-opacity"
                      >
                          Buy Again
                      </button>
                  </div>
               </div>
            ))}
          </div>
        ) : (
             <div className="flex flex-col items-center justify-center h-[50vh] text-center">
                <div className="h-20 w-20 rounded-full bg-gray-100 dark:bg-white/5 flex items-center justify-center mb-4">
                    <span className="material-symbols-outlined text-4xl text-gray-300 dark:text-gray-600">shopping_bag</span>
                </div>
                <h3 className="text-lg font-bold text-gray-900 dark:text-white">No orders yet</h3>
                <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">Start shopping to see your history.</p>
             </div>
        )}
      </div>
    </div>
  );
};

export default OrderHistory;

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

interface Member {
  id: string;
  name: string;
  isPrimary: boolean;
  fitData: any;
}

const Recommendation: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [members, setMembers] = useState<Member[]>([]);
  const [selectedMemberId, setSelectedMemberId] = useState<string>('');
  const [showMemberSelector, setShowMemberSelector] = useState(false);

  // Toast State
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('Added to Cart');
  const [isError, setIsError] = useState(false);

  const [cartCount, setCartCount] = useState(0);

  // Params from navigation
  const product = location.state?.product;
  const source = location.state?.source; // 'marketplace' or undefined

  // Default fallback product if none passed
  const displayProduct = product || {
    title: 'ZipRIGHT Hoodie',
    brand: 'Supreme',
    price: '$120',
    image: 'https://lh3.googleusercontent.com/aida-public/AB6AXuDQzhu543V1B17lxS38J-f4AO3UO_erZETw3hkkK35-JKgZoAufNLvMsnNkshG4--tD-ExdJWnbJjajDcrPL5K5NCD4Ll7toDLUjHETLIwrrD2NnNf8aLCOAqc477zHNabYy_EY5KzGuVuuQooxtkVk8pypuksy5VpbKtQLVPKcHuccMNJ5fJQDYxWr73ktujzPJqu4lZ0eFCsP8WUucrNgBxPNFis8jWShe9ninQEisbPqiQ5xwiQgKUN11OaQbG-QvfssHvhNoO0',
    category: 'Clothing',
    url: 'https://google.com'
  };

  // Resolve Product URL
  const productUrl = location.state?.productUrl || product?.url || displayProduct.url;

  const isClothing = displayProduct.category === 'Clothing';

  useEffect(() => {
    // Load Members
    const storedMembers = localStorage.getItem('zipright_members');
    if (storedMembers) {
      const parsedMembers = JSON.parse(storedMembers);
      setMembers(parsedMembers);

      // Check if memberId was passed via navigation state
      if (location.state && location.state.memberId) {
         setSelectedMemberId(location.state.memberId);
      } else {
         // Default to primary or first member if no state passed
         const primary = parsedMembers.find((m: Member) => m.isPrimary);
         setSelectedMemberId(primary ? primary.id : parsedMembers[0]?.id);
      }
    } else {
        // Fallback if no data
        const dummy: Member = { id: '1', name: 'My Fits', isPrimary: true, fitData: { topSize: 'L' }};
        setMembers([dummy]);
        setSelectedMemberId('1');
    }

    // Load Cart Count
    const cart = JSON.parse(localStorage.getItem('zipright_cart') || '[]');
    setCartCount(cart.reduce((acc: number, item: any) => acc + (item.quantity || 1), 0));
  }, [location.state]);

  const selectedMember = members.find(m => m.id === selectedMemberId);

  // Simulate different results based on selected member
  const recommendedSize = selectedMember?.fitData?.topSize || 'L';
  const matchPercentage = selectedMemberId === '1' ? 98 : Math.floor(Math.random() * (95 - 80 + 1)) + 80;

  // --- Visualizer Logic ---
  const [visualizedSize, setVisualizedSize] = useState(recommendedSize);

  useEffect(() => {
    setVisualizedSize(recommendedSize);
  }, [recommendedSize]);

  const sizes = ['XS', 'S', 'M', 'L', 'XL', 'XXL'];

  const getFitStatus = (visSize: string, recSize: string) => {
      const vIndex = sizes.indexOf(visSize);
      const rIndex = sizes.indexOf(recSize);
      if (vIndex === -1 || rIndex === -1) return 'unknown';
      if (vIndex < rIndex) return 'tight';
      if (vIndex === rIndex) return 'perfect';
      return 'loose';
  };

  const fitStatus = getFitStatus(visualizedSize, recommendedSize);

  const getShirtPath = (status: string) => {
      // SVG Paths adjusted for 200x200 viewbox
      switch(status) {
          case 'tight': return "M100,38 L122,44 L134,60 L118,68 L112,138 L88,138 L82,68 L66,60 L78,44 Z"; 
          case 'perfect': return "M100,38 L130,44 L146,64 L126,74 L126,142 L74,142 L74,74 L54,64 L70,44 Z";
          case 'loose': return "M100,38 L140,44 L162,68 L138,80 L142,146 L58,146 L62,80 L38,68 L60,44 Z";
          default: return "";
      }
  };
  // ------------------------

  const handleExternalBuy = () => {
    if (productUrl) {
      window.open(productUrl, '_blank');
    } else {
      alert("No product link provided to redirect to.");
    }
  };

  const addToCart = (silent: boolean = false) => {
    const existingCart = JSON.parse(localStorage.getItem('zipright_cart') || '[]');

    // Check limit
    const currentTotal = existingCart.reduce((acc: number, item: any) => acc + (item.quantity || 1), 0);
    if (currentTotal >= 10) {
        setToastMessage('Cart limit reached (Max 10)');
        setIsError(true);
        setShowToast(true);
        setTimeout(() => setShowToast(false), 2500);
        return false;
    }

    const priceNum = typeof displayProduct.price === 'string'
            ? parseFloat(displayProduct.price.replace(/[^0-9.-]+/g,""))
            : displayProduct.price;

    // Use visualized size if clothing, else one size
    const size = isClothing ? visualizedSize : 'One Size';

    // Check if item exists to group it
    const existingItemIndex = existingCart.findIndex((item: any) => 
        item.title === displayProduct.title && 
        item.brand === displayProduct.brand && 
        item.size === size
    );

    let newCart;
    if (existingItemIndex > -1) {
        newCart = [...existingCart];
        newCart[existingItemIndex].quantity = (newCart[existingItemIndex].quantity || 1) + 1;
    } else {
        const cartItem = {
            id: Date.now(),
            title: displayProduct.title,
            brand: displayProduct.brand,
            price: priceNum,
            size: size,
            image: displayProduct.image,
            quantity: 1
        };
        newCart = [...existingCart, cartItem];
    }

    localStorage.setItem('zipright_cart', JSON.stringify(newCart));

    // Update badge count
    setCartCount(newCart.reduce((acc: any, item: any) => acc + (item.quantity || 1), 0));

    if (!silent) {
        setToastMessage(`Added Size ${size} to Cart`);
        setIsError(false);
        setShowToast(true);
        setTimeout(() => setShowToast(false), 2500);
    }
    return true;
  };

  const handleBuyNow = () => {
    if (productUrl) {
        window.open(productUrl, '_blank');
    } else {
        alert("Product link unavailable.");
    }
  };

  const handleBack = () => {
    // Robust back navigation
    if (source === 'marketplace') {
      navigate('/marketplace');
    } else if (window.history.state && window.history.state.idx > 0) {
      navigate(-1);
    } else {
      navigate('/home');
    }
  };

  return (
    <div className="bg-[#f7f7f7] dark:bg-[#191919] text-gray-900 dark:text-white font-display min-h-screen flex flex-col antialiased relative">

      {/* Toast Notification */}
      <div className={`fixed top-20 left-1/2 -translate-x-1/2 z-[60] bg-black dark:bg-white text-white dark:text-black px-6 py-3 rounded-full shadow-xl flex items-center gap-2 transition-all duration-300 ${showToast ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'}`}>
         <span className={`material-symbols-outlined ${isError ? 'text-red-500' : 'text-green-400 dark:text-green-600'}`}>
            {isError ? 'error' : 'check_circle'}
         </span>
         <span className="font-bold text-sm">{toastMessage}</span>
      </div>

      {/* Top App Bar */}
      <div className="sticky top-0 z-50 flex items-center bg-[#f7f7f7]/80 dark:bg-[#191919]/80 backdrop-blur-md p-4 pb-2 justify-between border-b border-gray-200/50 dark:border-white/5">
        <button onClick={handleBack} className="flex size-10 shrink-0 items-center justify-center cursor-pointer rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>

        <div className="flex flex-col items-center flex-1">
            {isClothing ? (
                <>
                    <h2 className="text-sm font-bold leading-tight text-gray-500 dark:text-gray-400 uppercase tracking-wide">Shopping For</h2>
                    <button 
                        onClick={() => setShowMemberSelector(!showMemberSelector)}
                        className="flex items-center gap-1 text-black dark:text-white font-bold text-base active:opacity-70 transition-opacity"
                    >
                        {selectedMember?.name || 'Loading...'}
                        <span className="material-symbols-outlined text-sm pt-0.5">expand_more</span>
                    </button>
                </>
            ) : (
                <h2 className="text-base font-bold leading-tight text-black dark:text-white">Product Details</h2>
            )}
        </div>

        <button onClick={() => navigate('/cart')} className="relative flex size-10 shrink-0 items-center justify-center cursor-pointer rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors">
            <span className="material-symbols-outlined">shopping_bag</span>
            {cartCount > 0 && (
                <span className="absolute top-0 right-0 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[9px] font-bold text-white ring-2 ring-[#f7f7f7] dark:ring-[#191919]">
                    {cartCount}
                </span>
            )}
        </button>
      </div>

      {/* Member Selector Dropdown/Modal - Only for Clothing */}
      {showMemberSelector && isClothing && (
          <div className="absolute top-16 left-0 right-0 z-50 px-4 animate-in fade-in slide-in-from-top-4 duration-200">
              <div className="bg-white dark:bg-[#212121] rounded-2xl shadow-2xl border border-gray-100 dark:border-gray-700 p-2 flex flex-col gap-1">
                  {members.map(member => (
                      <button 
