                              <div className={`h-8 w-8 rounded-full flex items-center justify-center ${member.isPrimary ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-gray-200 text-gray-600'}`}>
                                <span className="material-symbols-outlined text-sm">{member.isPrimary ? 'person' : 'group'}</span>
                              </div>
                              <span className="font-bold text-sm">{member.name}</span>
                          </div>
                          {selectedMemberId === member.id && <span className="material-symbols-outlined text-green-500 text-sm">check</span>}
                      </button>
                  ))}
                  <div className="h-[1px] bg-gray-100 dark:bg-gray-700 my-1"></div>
                  <button 
                    onClick={() => navigate('/settings')}
                    className="flex items-center justify-center p-3 text-blue-600 dark:text-blue-400 font-bold text-sm"
                  >
                      Manage Profiles
                  </button>
              </div>
              <div className="fixed inset-0 z-[-1]" onClick={() => setShowMemberSelector(false)}></div>
          </div>
      )}

      {/* Main Content Scroll Area */}
      <div className="flex-1 overflow-y-auto no-scrollbar pb-48" onClick={() => setShowMemberSelector(false)}>

        {isClothing ? (
            /* --- LAYOUT 1: AI Recommendation (Clothing) --- */
            <>
                {/* Product Card */}
                <div className="p-4">
                <div className="flex items-stretch justify-between gap-4 rounded-xl bg-white dark:bg-[#212121] p-4 shadow-sm border border-gray-100 dark:border-gray-800">
                    <div className="flex flex-col justify-center gap-1 flex-[1.5_1.5_0px]">
                    <span className="inline-flex w-fit items-center gap-1 rounded-full bg-gray-100 dark:bg-white/10 px-2 py-0.5 text-xs font-medium text-gray-600 dark:text-gray-300">
                        Top Match
                    </span>
                    <p className="text-xl font-bold leading-tight mt-1 line-clamp-2">{displayProduct.title}</p>
                    <p className="text-gray-500 dark:text-[#ababab] text-sm font-normal leading-normal">{displayProduct.brand}</p>
                    </div>
                    <div 
                    className="w-24 h-24 sm:w-32 sm:h-32 bg-center bg-no-repeat bg-cover rounded-lg flex-shrink-0 border border-gray-100 dark:border-white/5"
                    style={{ backgroundImage: `url("${displayProduct.image}")` }}
                    ></div>
                </div>
                </div>

                {/* Main Recommendation Panel */}
                <div className="px-4 pb-6">
                    <div className="flex flex-col gap-4 rounded-xl border-2 border-black dark:border-white/20 bg-white dark:bg-[#212121] p-6 shadow-md relative overflow-hidden transition-all duration-300">
                        {/* Decorative background blob */}
                        <div className="absolute -top-10 -right-10 w-32 h-32 bg-green-500/10 rounded-full blur-2xl pointer-events-none"></div>

                        <div className="flex items-start justify-between">
                        <div className="flex flex-col gap-1 z-10">
                            <p className="text-xs font-bold text-gray-500 dark:text-[#ababab] uppercase tracking-wider">Recommended</p>
                            <p className="text-4xl font-black leading-tight">Size {recommendedSize}</p>
                        </div>
                        <div className="flex items-center justify-center rounded-lg bg-black dark:bg-white px-3 py-1.5 shadow-sm z-10">
                            <span className="material-symbols-outlined text-white dark:text-black text-[18px] mr-1">check_circle</span>
