                    </div>
                </div>

                {/* --- INTERACTIVE FIT VISUALIZER --- */}
                <div className="px-4 pb-6">
                    <div className="bg-white dark:bg-[#212121] rounded-3xl p-5 border border-gray-200 dark:border-white/10 shadow-sm relative overflow-hidden">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-bold text-lg text-black dark:text-white">Virtual Fit Check</h3>
                            <span className="text-[9px] font-black uppercase tracking-widest text-blue-500 bg-blue-50 dark:bg-blue-900/20 px-2 py-1 rounded">Beta</span>
                        </div>

                        {/* Visualizer Container */}
                        <div className="relative h-64 w-full bg-[#f0f0f0] dark:bg-[#1a1a1a] rounded-2xl flex items-center justify-center mb-6 overflow-hidden border border-dashed border-gray-300 dark:border-white/10">
