                            </svg>

                            {/* Dynamic Garment */}
                            <svg width="200" height="220" viewBox="0 0 200 220" className="absolute transition-all duration-500 ease-out z-10" style={{ color: fitStatus === 'tight' ? '#ef4444' : fitStatus === 'perfect' ? '#22c55e' : '#3b82f6' }}>
                                <path 
                                    d={getShirtPath(fitStatus)} 
                                    fill="currentColor" 
                                    fillOpacity="0.25" 
                                    stroke="currentColor" 
                                    strokeWidth="3"
                                    strokeLinecap="round" 
                                    strokeLinejoin="round"
                                    className="drop-shadow-lg transition-all duration-500"
                                />
