                                {fitStatus === 'tight' && (
                                    <g fill="#ef4444" fillOpacity="0.6">
                                        <circle cx="78" cy="65" r="5" filter="blur(3px)" className="animate-pulse" />
                                        <circle cx="122" cy="65" r="5" filter="blur(3px)" className="animate-pulse" />
                                        <ellipse cx="100" cy="110" rx="12" ry="4" filter="blur(4px)" className="animate-pulse" />
                                    </g>
                                )}
                                {/* Draping for Loose Fit */}
                                {fitStatus === 'loose' && (
                                    <g stroke="currentColor" strokeWidth="1" strokeOpacity="0.5" fill="none">
                                        <path d="M70,120 Q80,140 90,120" />
                                        <path d="M130,120 Q120,140 110,120" />
                                    </g>
                                )}
                            </svg>

                            {/* Label Overlay */}
                            <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-white/90 dark:bg-black/80 backdrop-blur-md px-3 py-1.5 rounded-full border border-black/5 dark:border-white/10 shadow-lg z-20">
