  ];

  // Profile Data State
  const [profileData, setProfileData] = useState({
    firstName: '',
    email: '',
    dob: '',
    gender: ''
  });

  const [isLoading, setIsLoading] = useState(false);
  const [isResending, setIsResending] = useState(false);
  const [resendMessage, setResendMessage] = useState('');
  const [error, setError] = useState('');
  const [tokenClient, setTokenClient] = useState<any>(null);

  useEffect(() => {
    const initializeGoogle = () => {
      if (window.google && window.google.accounts) {
        const client = window.google.accounts.oauth2.initTokenClient({
          client_id: GOOGLE_CLIENT_ID,
          scope: 'https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/userinfo.email',
          callback: (response: any) => handleGoogleResponse(response),
        });
        setTokenClient(client);
      }
    };

    if (window.google) {
      initializeGoogle();
    } else {
      const interval = setInterval(() => {
        if (window.google) {
          initializeGoogle();
          clearInterval(interval);
        }
      }, 100);
      return () => clearInterval(interval);
    }
  }, []);

  // Reset phone if it exceeds length when country changes
  useEffect(() => {
     if (phone.length > selectedCountry.requiredLength) {
         setPhone(phone.substring(0, selectedCountry.requiredLength));
     }
  }, [selectedCountry, phone]);

  const handleGoogleResponse = async (tokenResponse: any) => {
    if (tokenResponse.error) {
      setIsLoading(false);
      setError('Google Sign-In failed. Please try again.');
      return;
    }

    try {
      const userInfoResponse = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
        headers: { Authorization: `Bearer ${tokenResponse.access_token}` },
      });

      if (!userInfoResponse.ok) throw new Error('Failed to fetch user profile');

      const googleUser = await userInfoResponse.json();

      const appUser = {
        id: googleUser.sub,
        firstName: googleUser.given_name,
        lastName: googleUser.family_name,
        email: googleUser.email,
        photoUrl: googleUser.picture,
        token: tokenResponse.access_token,
        provider: 'google'
      };

      localStorage.setItem('zipright_user', JSON.stringify(appUser));

      // Initialize Member Profile if not exists (Critical for app functionality)
      const storedMembers = localStorage.getItem('zipright_members');
      let members = storedMembers ? JSON.parse(storedMembers) : [];

      if (!members.some((m: any) => m.isPrimary)) {
        const newProfile = {
          id: googleUser.sub,
          name: googleUser.given_name || 'My Fits',
          isPrimary: true,
          fitData: {
            brand: 'Nike',
            topSize: 'M',
            waistSize: '32',
            heightUnit: 'ft',
            heightFt: '5',
            heightIn: '10',
            weight: '75',
            fitPreference: 2
          }
        };
        members = [newProfile, ...members];
        localStorage.setItem('zipright_members', JSON.stringify(members));
      }

      setIsLoading(false);
      navigate('/how-it-works');
    } catch (err) {
      console.error(err);
      setError('Failed to retrieve user data.');
      setIsLoading(false);
    }
  };

  const handleGoogleLogin = () => {
    setError('');
    if (tokenClient) {
      setIsLoading(true);
      // prompt: 'select_account' ensures the account chooser is always shown
      tokenClient.requestAccessToken({ prompt: 'select_account' });
    } else {
      setError('Google services are initializing. Please wait a moment.');
    }
  };

  const handleBack = () => {
    if (step === 'input') navigate('/welcome');
    else if (step === 'otp') setStep('input');
    else if (step === 'profile') setStep('input');
    else setStep('input');
  };

  const handleContinue = () => {
    setError('');
    if (authMethod === 'phone') {
      if (!phone || phone.length !== selectedCountry.requiredLength) {
        setError(`Please enter a valid ${selectedCountry.requiredLength}-digit mobile number`);
        return;
      }
      setIsLoading(true);
      setTimeout(() => {
        setIsLoading(false);
        setStep('otp');
      }, 1000);
    }
  };

  const handleVerifyOtp = () => {
    setIsLoading(true);
    // Simulate verification delay
    setTimeout(() => {
        setIsLoading(false);
        if (isSignUp) {
            setStep('profile');
        } else {
            // Mock Login: Proceed to app
            navigate('/how-it-works');
        }
    }, 1500);
  };

  const handleResendCode = () => {
    if (isResending) return;
    setIsResending(true);
    setResendMessage('');
    // Simulate API call to resend OTP
    setTimeout(() => {
        setIsResending(false);
        setResendMessage(`Verification code sent to ${selectedCountry.code} ${phone}`);
        // Clear message after 5 seconds to keep UI clean
        setTimeout(() => setResendMessage(''), 5000);
    }, 2000);
  };

  const handleSaveProfile = () => {
      if (!profileData.firstName || !profileData.email) {
          setError("First name and email are required.");
          return;
      }
      setError('');
      setIsLoading(true);

      setTimeout(() => {
        const user = {
            id: Date.now().toString(),
            firstName: profileData.firstName,
            email: profileData.email,
            dob: profileData.dob,
            gender: profileData.gender,
            phone: `${selectedCountry.code} ${phone}`,
            provider: 'phone',
            photoUrl: 'https://lh3.googleusercontent.com/aida-public/AB6AXuD-1kcOw2tgZtvs4NjR7JxXA2NvWlq8KIK-jsA_k137V4zcnbROU0ulf5ANlMTh7y4AL80O2zjMpJFO55QNk04o5v4ZVs81oYdv48c2n8qwWKzJP2M5fg2W8dVnW0gpYFtEx90vxHV4HoAAP08Uf1MVtZCQ_f0vdTs52zOtUghq0OEkedFlAi2-aPbh79HlHFdbIrTlJ4hvnG4qoEFCLB9aLAxWg9B4woWxF0IFkAk2-trm4o8FlX_koqXGUeLhWAnWx_oxwZdn4fo'
        };
        localStorage.setItem('zipright_user', JSON.stringify(user));

        // Create initial member profile
        const member = {
            id: user.id,
            name: user.firstName,
            isPrimary: true,
            fitData: {
                brand: 'Nike',
                topSize: 'M',
                waistSize: '32',
                heightUnit: 'ft',
                heightFt: '5',
                heightIn: '10',
                weight: '70',
                fitPreference: 2
            }
        };
        localStorage.setItem('zipright_members', JSON.stringify([member]));

        setIsLoading(false);
        navigate('/how-it-works');
      }, 1500);
  };

  const handleOtpChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;

    const newOtp = [...otp];
    newOtp[index] = value.slice(-1);
    setOtp(newOtp);

    if (newOtp[index] !== '' && index < 3) {
      otpRefs[index + 1].current?.focus();
    }
  };

  const handleOtpKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Backspace' && otp[index] === '' && index > 0) {
      otpRefs[index - 1].current?.focus();
    }
  };

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col bg-[#050505] font-display text-white transition-colors duration-500">
      {/* Back Button */}
      <div className="px-6 py-6 pt-8">
        <button onClick={handleBack} className="h-11 w-11 flex items-center justify-center rounded-full bg-white/10 hover:bg-white/20 active:scale-95 transition-all">
          <span className="material-symbols-outlined text-white">arrow_back</span>
        </button>
      </div>

      <div className="flex-1 flex flex-col px-6">
        {step === 'input' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-sm mx-auto w-full">
            <h1 className="text-3xl font-bold text-white mb-2">
              {isSignUp ? 'Create account' : 'Welcome back'}
            </h1>
            <p className="text-gray-400 font-medium mb-10">
              Please enter your details.
            </p>

            <div className="flex flex-col gap-3 mb-8">
              <button 
                onClick={handleGoogleLogin} 
                disabled={isLoading}
                className="relative flex h-14 w-full items-center justify-center rounded-xl bg-white/5 border border-white/10 shadow-sm active:scale-95 transition-all hover:bg-white/10"
              >
                {isLoading ? (
                  <div className="flex items-center gap-3">
                    <div className="h-5 w-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-bold text-white">Connecting...</span>
                  </div>
                ) : (
                  <>
                    <img src="https://www.svgrepo.com/show/475656/google-color.svg" className="h-5 w-5 absolute left-6" alt="G" />
                    <span className="font-bold text-white tracking-wide">Continue with Google</span>
                  </>
                )}
              </button>
            </div>

            <div className="flex gap-3 mb-4 h-14">
              {/* Country Code Selector Box */}
              <div className="relative w-24">
                <button 
                  onClick={() => setShowCountryPicker(!showCountryPicker)}
                  className="flex h-full w-full items-center justify-center gap-1 rounded-xl border border-white/10 bg-[#0F0F0F] px-2 hover:bg-white/5 transition-all text-sm font-bold text-gray-400"
                >
                  {selectedCountry.code}
                  <span className="material-symbols-outlined text-sm pt-0.5">expand_more</span>
                </button>

                {showCountryPicker && (
                  <div className="absolute top-full left-0 right-0 mt-2 z-50 bg-[#1C1C1E] border border-white/10 rounded-xl overflow-hidden shadow-2xl max-h-48 overflow-y-auto no-scrollbar">
                    {countryCodes.map(c => (
                      <button 
                        key={c.iso}
                        onClick={() => { setSelectedCountry(c); setShowCountryPicker(false); }}
                        className="w-full text-left px-4 py-3 hover:bg-white/5 text-sm font-bold border-b border-white/5 last:border-none"
                      >
                        {c.code} {c.name}
                      </button>
                    ))}
                  </div>
                )}
              </div>

              {/* Mobile Number Input Box */}
              <div className="flex-1">
                <input
                  type="tel"
                  value={phone}
                  onChange={(e) => {
                      const val = e.target.value.replace(/\D/g, '');
                      if (val.length <= selectedCountry.requiredLength) {
                          setPhone(val);
                      }
                  }}
                  placeholder="Mobile number"
                  className="h-full w-full rounded-xl border border-white/10 bg-[#0F0F0F] px-5 font-bold outline-none focus:ring-1 focus:ring-white/20 transition-all placeholder:text-gray-600"
                />
              </div>
            </div>

            {error && <p className="mb-4 text-center text-xs font-bold text-red-500">{error}</p>}

            <div className="mt-4 flex flex-col gap-10">
               <button 
                 onClick={handleContinue}
                 disabled={isLoading}
                 className="h-14 w-full rounded-full bg-white text-black font-bold text-base shadow-[0_0_20px_rgba(255,255,255,0.3)] active:scale-95 transition-all flex items-center justify-center gap-2"
               >
                 {isLoading ? 'Processing...' : (
                   <>
                     Continue
                     <span className="material-symbols-outlined text-xl">arrow_forward</span>
                   </>
                 )}
               </button>

               <p className="text-center text-sm font-medium text-gray-500">
                {isSignUp ? 'Already have an account? ' : "Don't have an account? "}
                <button onClick={() => setIsSignUp(!isSignUp)} className="font-bold text-white hover:underline transition-all">
                  {isSignUp ? 'Log in' : 'Sign up'}
                </button>
              </p>
            </div>
          </div>
        )}

        {step === 'otp' && (
          <div className="animate-in fade-in zoom-in-95 duration-500 flex flex-col items-center max-w-sm mx-auto w-full">
            <h1 className="text-[32px] font-bold text-white mb-2">Verify Phone</h1>
            <p className="text-gray-500 font-medium mb-12">We've sent a code to your mobile.</p>

            <div className="flex justify-center gap-4 mb-12">
              {otp.map((digit, i) => (
                <div key={i} className="relative group">
                  <input 
                    ref={otpRefs[i]}
                    type="text" 
                    inputMode="numeric"
                    maxLength={1}
                    value={digit}
                    onChange={(e) => handleOtpChange(i, e.target.value)}
                    onKeyDown={(e) => handleOtpKeyDown(i, e)}
                    className="h-16 w-14 rounded-2xl border border-transparent bg-[#111111] text-center text-[28px] font-black outline-none focus:ring-1 focus:ring-white/40 transition-all" 
                    autoFocus={i === 0}
                  />
                  <div className={`absolute bottom-3 left-1/2 -translate-x-1/2 w-4 h-[2px] rounded-full bg-white/10 transition-opacity ${digit === '' ? 'opacity-100' : 'opacity-0'}`}></div>
                </div>
              ))}
            </div>

            <div className="w-full">
                <button 
                  onClick={handleVerifyOtp} 
                  className="h-14 w-full rounded-full bg-white text-black font-bold text-lg shadow-[0_0_20px_rgba(255,255,255,0.4)] hover:shadow-[0_0_30px_rgba(255,255,255,0.6)] active:scale-95 transition-all flex items-center justify-center gap-2"
                  disabled={isLoading}
                >
                  {isLoading ? 'Verifying...' : 'Verify Code'}
                </button>
            </div>

            <div className="mt-12 flex flex-col items-center gap-3">
                <button 
                    onClick={handleResendCode}
                    disabled={isResending || resendMessage !== ''}
                    className={`text-sm font-bold transition-colors ${isResending || resendMessage !== '' ? 'text-gray-600 cursor-not-allowed' : 'text-gray-500 hover:text-white'}`}
                >
                    {isResending ? 'Sending...' : 'Resend code'}
                </button>
                {resendMessage && (
                    <p className="text-[11px] text-gray-400 font-medium animate-in fade-in zoom-in-95 duration-300 bg-white/5 px-3 py-1.5 rounded-lg border border-white/5 flex items-center gap-2">
                        <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
                        {resendMessage}
                    </p>
                )}
            </div>
          </div>
        )}

        {step === 'profile' && (
           <div className="animate-in fade-in slide-in-from-right duration-500 max-w-sm mx-auto w-full">
               <h1 className="text-3xl font-bold text-white mb-2">Setup Profile</h1>
               <p className="text-gray-400 font-medium mb-8">
                 Tell us a bit about yourself.
               </p>

               <div className="flex flex-col gap-5">
                   {/* Name */}
                   <div>
                       <label className="text-xs font-bold text-gray-500 uppercase tracking-wider ml-1 mb-2 block">First Name</label>
                       <input 
                           type="text" 
                           value={profileData.firstName}
                           onChange={(e) => setProfileData({...profileData, firstName: e.target.value})}
                           className="w-full h-14 rounded-xl bg-[#111] border border-white/10 px-5 text-white font-bold outline-none focus:border-white/30 transition-colors"
                           placeholder="Enter your name"
                       />
                   </div>

                    {/* Email */}
                   <div>
                       <label className="text-xs font-bold text-gray-500 uppercase tracking-wider ml-1 mb-2 block">Email</label>
                       <input 
                           type="email" 
                           value={profileData.email}
                           onChange={(e) => setProfileData({...profileData, email: e.target.value})}
                           className="w-full h-14 rounded-xl bg-[#111] border border-white/10 px-5 text-white font-bold outline-none focus:border-white/30 transition-colors"
                           placeholder="Enter your email"
                       />
                   </div>

                   <div className="flex gap-4">
                       {/* DOB */}
                       <div className="flex-1">
                           <label className="text-xs font-bold text-gray-500 uppercase tracking-wider ml-1 mb-2 block">Date of Birth</label>
                           <input 
                               type="date" 
                               value={profileData.dob}
                               onChange={(e) => setProfileData({...profileData, dob: e.target.value})}
                               className="w-full h-14 rounded-xl bg-[#111] border border-white/10 px-4 text-white font-bold outline-none focus:border-white/30 transition-colors"
                               style={{ colorScheme: 'dark' }}
                           />
                       </div>

                       {/* Gender */}
                       <div className="flex-1">
                           <label className="text-xs font-bold text-gray-500 uppercase tracking-wider ml-1 mb-2 block">Gender</label>
                           <select 
                               value={profileData.gender}
                               onChange={(e) => setProfileData({...profileData, gender: e.target.value})}
                               className="w-full h-14 rounded-xl bg-[#111] border border-white/10 px-4 text-white font-bold outline-none focus:border-white/30 transition-colors appearance-none"
                           >
                               <option value="" disabled>Select</option>
                               <option value="Male">Male</option>
                               <option value="Female">Female</option>
                               <option value="Non-Binary">Non-Binary</option>
                               <option value="Other">Other</option>
                           </select>
                       </div>
                   </div>

                   {/* Phone (Read Only) */}
                   <div>
                       <label className="text-xs font-bold text-gray-500 uppercase tracking-wider ml-1 mb-2 block">Phone Number</label>
                       <div className="w-full h-14 rounded-xl bg-[#111] border border-white/5 px-5 flex items-center text-gray-400 font-bold">
                           {selectedCountry.code} {phone}
                           <span className="material-symbols-outlined ml-auto text-green-500 text-lg">check_circle</span>
                       </div>
                   </div>

                   {error && <p className="text-center text-xs font-bold text-red-500">{error}</p>}
               </div>

               <button 
                   onClick={handleSaveProfile}
                   disabled={isLoading}
                   className="mt-10 h-14 w-full rounded-full bg-white text-black font-bold text-lg shadow-[0_0_20px_rgba(255,255,255,0.4)] hover:scale-[1.01] active:scale-[0.99] transition-all flex items-center justify-center gap-2"
               >
                   {isLoading ? 'Creating Account...' : 'Complete Setup'}
               </button>
           </div>
        )}
      </div>

      {showCountryPicker && <div className="fixed inset-0 z-40" onClick={() => setShowCountryPicker(false)}></div>}
    </div>
  );
};

