import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const FashionStudio: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  // State
  const [selectedItem, setSelectedItem] = useState(0);
  const [isLiked, setIsLiked] = useState(false);
  const [showToast, setShowToast] = useState(false);

  // Rotation State
  const [rotation, setRotation] = useState(0);
  const dragStartX = useRef<number | null>(null);
  const startRotation = useRef(0);

  // Wardrobe Data
  const [wardrobe, setWardrobe] = useState([
    {
      id: 0,
      name: 'Structured Wool Coat',
      brand: 'The Row',
      price: '₹24,500',
      image: 'https://images.unsplash.com/photo-1591047139829-d91aecb6caea?auto=format&fit=crop&w=800&q=80', // Jacket
      category: 'Outerwear'
    },
    {
      id: 1,
      name: 'Oversized Hoodie',
      brand: 'Fear of God',
      price: '₹12,000',
      image: 'https://images.unsplash.com/photo-1556905055-8f358a7a47b2?auto=format&fit=crop&w=800&q=80', // Hoodie
      category: 'Tops'
    },
    {
      id: 2,
      name: 'Silk Slip Dress',
      brand: 'Anine Bing',
      price: '₹3,500',
      image: 'https://images.unsplash.com/photo-1595777457583-95e059d581b8?auto=format&fit=crop&w=800&q=80', // Dress
      category: 'Dresses'
    },
    {
      id: 3,
      name: 'Denim Jacket',
      brand: 'Levi\'s',
      price: '₹4,500',
      image: 'https://images.unsplash.com/photo-1543076447-215ad9ba6923?auto=format&fit=crop&w=800&q=80', // Denim
      category: 'Outerwear'
    }
  ]);

  const currentItem = wardrobe.find(item => item.id === selectedItem) || wardrobe[0];

  // Handle incoming product from Marketplace
  useEffect(() => {
    if (location.state?.product) {
      const incoming = location.state.product;
      const existingItem = wardrobe.find(item => item.image === incoming.image);

      if (existingItem) {
        setSelectedItem(existingItem.id);
      } else {
        const newId = Date.now();
        const newItem = {
          id: newId,
          name: incoming.title,
          brand: incoming.brand,
          price: incoming.price,
          image: incoming.image,
          category: incoming.category
        };
        setWardrobe(prev => [...prev, newItem]);
        setSelectedItem(newId);
      }
    }
  }, [location.state]);

  // Check Wishlist Status
  useEffect(() => {
    const wishlist = JSON.parse(localStorage.getItem('zipright_wishlist') || '[]');
    // Check if item exists in wishlist (matching by name since IDs might conflict with other pages)
    const exists = wishlist.some((item: any) => item.title === currentItem.name);
    setIsLiked(exists);
  }, [currentItem]);

  // Reset rotation when item changes
  useEffect(() => {
    setRotation(0);
    startRotation.current = 0;
  }, [selectedItem]);

  // Initialize Camera
  useEffect(() => {
    let localStream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        // Stop any existing tracks before starting a new stream
        if (stream) {
          stream.getTracks().forEach(track => track.stop());
        }

        const mediaStream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: facingMode,
            height: { ideal: 1920 },
            width: { ideal: 1080 }
          }, 
          audio: false 
        });

        localStream = mediaStream;
        setStream(mediaStream);

        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
        }
        setError(null);
      } catch (err) {
        console.error("Camera access denied:", err);
        setError("Please enable camera access to use Virtual Try-On.");
      }
    };

    startCamera();

    return () => {
      if (localStream) {
        localStream.getTracks().forEach(track => track.stop());
      }
    };
  }, [facingMode]);

  const handleBack = () => {
    if (stream) {
        stream.getTracks().forEach(track => track.stop());
    }
    if (window.history.state && window.history.state.idx > 0) {
        navigate(-1);
    } else {
        navigate('/home');
    }
  };

  const toggleCamera = () => {
    // Stop current stream to ensure clean switch
    if (stream) {
        stream.getTracks().forEach(track => track.stop());
        setStream(null); 
    }
    setFacingMode(prev => prev === 'user' ? 'environment' : 'user');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const imageUrl = URL.createObjectURL(file);

      const newItem = {
        id: wardrobe.length > 0 ? Math.max(...wardrobe.map(i => i.id)) + 1 : 0,
        name: 'Custom Upload',
        brand: 'My Closet',
        price: '',
        image: imageUrl,
        category: 'Custom'
      };

      setWardrobe(prev => [...prev, newItem]);
      setSelectedItem(newItem.id);
    }
  };

  const handleAddToCart = () => {
      const cart = JSON.parse(localStorage.getItem('zipright_cart') || '[]');

      // Parse price safely (remove currency symbols and commas)
      const priceString = currentItem.price || '0';
      const priceNum = parseFloat(priceString.replace(/[^0-9.]/g, '')) || 0;

      // Check if item exists to update quantity, else add new
      const existingItemIndex = cart.findIndex((item: any) => 
        item.title === currentItem.name && item.brand === currentItem.brand
      );

      let newCart;
      if (existingItemIndex > -1) {
          newCart = [...cart];
          newCart[existingItemIndex].quantity = (newCart[existingItemIndex].quantity || 1) + 1;
      } else {
          const newItem = {
              id: Date.now(),
              title: currentItem.name,
              brand: currentItem.brand,
              price: priceNum,
              size: 'M', // Default size for AR items
              image: currentItem.image,
              quantity: 1
          };
          newCart = [...cart, newItem];
      }

      localStorage.setItem('zipright_cart', JSON.stringify(newCart));

      // Show Toast
      setShowToast(true);
      setTimeout(() => setShowToast(false), 2500);
  };

  const toggleWishlist = () => {
      const wishlist = JSON.parse(localStorage.getItem('zipright_wishlist') || '[]');
      let newWishlist;

      if (isLiked) {
          // Remove
          newWishlist = wishlist.filter((item: any) => item.title !== currentItem.name);
      } else {
          // Add
          const newItem = {
              id: Date.now(),
              title: currentItem.name,
              brand: currentItem.brand,
              price: currentItem.price,
              image: currentItem.image,
              verified: true
          };
          newWishlist = [...wishlist, newItem];
      }

      localStorage.setItem('zipright_wishlist', JSON.stringify(newWishlist));
      setIsLiked(!isLiked);
      if (navigator.vibrate) navigator.vibrate(10);
  };

  // --- Drag to Rotate Logic (Touch & Mouse) ---
  const handleDragStart = (clientX: number) => {
      dragStartX.current = clientX;
      startRotation.current = rotation;
  };

  const handleDragMove = (clientX: number) => {
      if (dragStartX.current !== null) {
          const diff = clientX - dragStartX.current;
          // Sensitivity: 1 pixel = 0.5 degree
          setRotation(startRotation.current + diff * 0.5);
      }
  };

  const handleDragEnd = () => {
      dragStartX.current = null;
  };

  // Touch Events
  const handleTouchStart = (e: React.TouchEvent) => handleDragStart(e.touches[0].clientX);
  const handleTouchMove = (e: React.TouchEvent) => handleDragMove(e.touches[0].clientX);
  const handleTouchEnd = () => handleDragEnd();

  // Mouse Events
  const handleMouseDown = (e: React.MouseEvent) => handleDragStart(e.clientX);
  const handleMouseMove = (e: React.MouseEvent) => handleDragMove(e.clientX);
  const handleMouseUp = () => handleDragEnd();
  const handleMouseLeave = () => handleDragEnd();

  return (
    <div 
        className="relative h-screen w-full bg-black text-white overflow-hidden font-display select-none cursor-grab active:cursor-grabbing"
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseLeave}
    >

      {/* Toast Notification */}
      <div className={`fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-white/90 backdrop-blur-md text-black px-6 py-3 rounded-full shadow-2xl border border-white/20 flex items-center gap-3 transition-all duration-500 ease-out pointer-events-none ${showToast ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 -translate-y-4 scale-90'}`}>
         <span className="material-symbols-outlined text-green-600 filled" style={{ fontVariationSettings: "'FILL' 1" }}>check_circle</span>
         <span className="font-bold text-sm tracking-wide">Added to Cart</span>
      </div>

      {/* Hidden File Input for Sidebar + Button */}
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleImageUpload} 
      />

      {/* 1. Live Camera Background */}
      <div className="absolute inset-0 z-0 bg-[#101010]">
        {error ? (
            <div className="flex flex-col items-center justify-center h-full p-6 text-center">
                <span className="material-symbols-outlined text-gray-500 text-5xl mb-4">no_photography</span>
                <p className="text-gray-400 font-bold">{error}</p>
            </div>
        ) : (
            <video 
                ref={videoRef}
                autoPlay 
                playsInline 
                muted 
                // Mirror the video only when using the front (user) camera
                className={`w-full h-full object-cover transition-transform duration-500 ${facingMode === 'user' ? 'scale-x-[-1]' : 'scale-x-1'}`} 
            />
        )}

        {/* Dark overlay for UI visibility */}
        <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-transparent to-black/80 pointer-events-none"></div>
      </div>

      {/* 2. Top Minimal Navbar */}
      <div className="absolute top-0 left-0 right-0 z-50 flex items-center justify-between px-6 py-6">
        <button 
          onClick={handleBack} 
          className="h-11 w-11 flex items-center justify-center rounded-full bg-black/20 backdrop-blur-md border border-white/10 active:scale-90 transition-all hover:bg-black/40"
        >
          <span className="material-symbols-outlined text-white text-[20px]">arrow_back</span>
        </button>

        <div className="flex flex-col items-center opacity-90 drop-shadow-md">
          <span className="text-[10px] font-black uppercase tracking-[0.2em] text-white/80">AR Live Mode</span>
        </div>

        <div className="flex items-center gap-3">
           {/* Camera Toggle Button */}
           <button 
             onClick={toggleCamera}
             className="h-11 w-11 flex items-center justify-center rounded-full bg-black/20 backdrop-blur-md border border-white/10 active:scale-90 transition-all hover:bg-black/40"
           >
              <span className="material-symbols-outlined text-white text-[18px]">cameraswitch</span>
           </button>
        </div>
      </div>

      {/* 3. AR Cloth Overlay (Smart Mirror Effect) */}
      <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
          <div 
            className="relative w-full max-w-sm h-[70vh] flex items-center justify-center opacity-90 mix-blend-normal transition-transform duration-75 ease-out"
            style={{ transform: `perspective(1000px) rotateY(${rotation}deg)` }}
          >
              <img 
                src={currentItem.image} 
                alt="AR Cloth"
                className="w-full h-full object-contain drop-shadow-2xl animate-in fade-in slide-in-from-bottom-8 duration-700 ease-out"
                key={currentItem.id}
              />

              {/* Optional: Guide Silhouette for positioning */}
              <div className="absolute inset-0 border-2 border-white/5 rounded-[4rem] pointer-events-none"></div>

              {/* 360 Hint - Disappears when rotated */}
              {rotation === 0 && (
                  <div className="absolute bottom-10 flex items-center gap-2 px-3 py-1.5 bg-black/40 rounded-full backdrop-blur-sm border border-white/10 animate-pulse">
                      <span className="material-symbols-outlined text-[14px]">360</span>
                      <span className="text-[10px] font-bold uppercase tracking-wider">Drag to Rotate</span>
                  </div>
              )}
          </div>
      </div>

      {/* 4. Left Sidebar - Carousel of Items */}
      <div className="absolute left-4 top-1/2 -translate-y-1/2 z-40 w-[80px] max-h-[60vh] flex flex-col items-center py-5 rounded-[3rem] bg-black/40 backdrop-blur-xl border border-white/10 overflow-hidden shadow-2xl ring-1 ring-white/5">
          <div className="flex-1 w-full overflow-y-auto no-scrollbar flex flex-col items-center gap-4 px-2 py-1">
            {wardrobe.map((item) => (
                <button
                    key={item.id}
                    onClick={() => setSelectedItem(item.id)}
                    className={`relative w-12 h-12 rounded-2xl flex-shrink-0 overflow-hidden transition-all duration-500 ease-out group ${
                        selectedItem === item.id 
                        ? 'scale-110 z-10 shadow-[0_0_25px_rgba(255,255,255,0.3)] ring-2 ring-white' 
                        : 'opacity-60 hover:opacity-100 hover:scale-105 grayscale hover:grayscale-0'
                    }`}
                >
                    <img src={item.image} className="w-full h-full object-cover" alt={item.name} />
                    {selectedItem === item.id && (
                        <div className="absolute inset-0 bg-gradient-to-tr from-white/10 to-transparent"></div>
                    )}
                </button>
            ))}
          </div>

          {/* Functional Upload Button in Sidebar Footer */}
          <div className="w-full px-2 pt-4 mt-2 border-t border-white/10">
            <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-12 h-12 rounded-full bg-white/10 hover:bg-white hover:text-black flex items-center justify-center text-white transition-all mx-auto active:scale-90 hover:shadow-[0_0_15px_rgba(255,255,255,0.5)] duration-300"
            >
                <span className="material-symbols-outlined text-[20px]">add</span>
            </button>
          </div>
      </div>

      {/* 5. Bottom Info */}
      <div className="absolute bottom-0 left-0 right-0 p-6 pb-10 z-50 bg-gradient-to-t from-black via-black/90 to-transparent pointer-events-none">
          <div className="flex flex-col items-center pointer-events-auto">

              {/* Item Info - Animated Text */}
              <div className="mb-8 text-center" key={currentItem.id}>
                  <h2 className="text-2xl font-black text-white leading-tight shadow-black drop-shadow-md animate-in slide-in-from-bottom-2 fade-in duration-500">{currentItem.name}</h2>
                  <p className="text-xs font-bold text-gray-400 uppercase tracking-[0.15em] mt-1.5 animate-in slide-in-from-bottom-2 fade-in duration-500 delay-100">{currentItem.brand}</p>
              </div>

              {/* Action Buttons */}
              <div className="flex gap-4 w-full max-w-sm">
                  <button 
                    onClick={handleAddToCart}
                    className="flex-1 h-14 rounded-2xl bg-white text-black font-black uppercase tracking-wider flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(255,255,255,0.15)] active:scale-[0.98] transition-all hover:bg-gray-100 hover:shadow-[0_0_30px_rgba(255,255,255,0.3)] hover:-translate-y-0.5 duration-300"
                  >
                      <span className="material-symbols-outlined text-[22px]">shopping_bag</span>
                      Add to Cart
                  </button>
                  <button 
                    onClick={toggleWishlist}
                    className="h-14 w-14 rounded-2xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center text-white active:scale-90 hover:bg-white/20 hover:border-white/40 transition-all duration-300 group"
                  >
                      <span className={`material-symbols-outlined text-[24px] transition-transform group-hover:scale-110 ${isLiked ? 'text-red-500 filled' : 'text-white'}`} style={isLiked ? { fontVariationSettings: "'FILL' 1" } : {}}>
                        favorite
                      </span>
                  </button>
              </div>

          </div>
      </div>

    </div>
  );
};

